-- 0258 turismo_religioso (inventario_turismo_religioso_pdf) — entidades + puntuaciones
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('04003','religioso','Santuario de Nuestra Señora del Saliente (Monasterio del Saliente)','Gran peregrinación la noche del 7 al 8 de septiembre, donde miles de devotos caminan a pie desde diversos puntos de la comarca del Valle del Almanzora y provincias limítrofes recorriendo la rambla hasta el santuario barroco en la Sierra de las Estancias.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90423','religioso','Santuario de la Virgen de Gádor','La Bajada de la Virgen desde su santuario hasta la Iglesia Parroquial de la Anunciación se realiza el segundo domingo de Cuaresma, permaneciendo en el centro urbano para su novena hasta la subida el cuarto domingo de Cuaresma.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90736','religioso','Iglesia Parroquial de la Santa Cruz de Canjáyar','Fiestas patronales del 17 al 20 de abril. La procesión de la Santa Cruz el 19 de abril conmemora el milagro de su aparición, acompañada de ritos de veneración de la reliquia y levantamiento de cruces efímeras.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('04038','religioso','Santuario del Cristo de la Luz','Tercer domingo de septiembre. Es catalogada como una de las romerías más multitudinarias del sur de España. Destaca la masiva procesión nocturna caracterizada por la quema integrada y continua de miles de kilos de pólvora (cohetes) como ofrenda extrema de los peregrinos.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('04012','religioso','Ermita de San Sebastián y Fiesta de Moros y Cristianos','Celebrada el fin de semana más cercano al 20 de enero. Consiste en una de las representaciones de Moros y Cristianos de mayor pureza litúrgica y etnográfica de la provincia, donde las imágenes del santo sufren "cautiverios" y rescates simbólicos ritualizados.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('04013','religioso','Iglesia Parroquial de Nuestra Señora de la Asunción y Capilla del Paso Negro','Celebración de la Semana Santa (Declarada de Interés Turístico Nacional). Destacan los desfiles procesionales del Miércoles Santo (Paso Blanco) y Jueves Santo (Paso Negro), caracterizados por una rigurosa puesta en escena de corte histórico-bíblico y una enorme rivalidad devocional.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('04004','religioso','Santuario de Nuestra Señora del Mar e Iglesia de la Virgen del Mar','Fiestas patronales en la segunda quincena de agosto. El acto central es la procesión de la Virgen el último domingo de agosto, junto con la tradicional romería a la playa de Torregarcía el segundo domingo de enero, conmemorando el lugar exacto del hallazgo de la imagen.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('04063','religioso','Ermita de la Virgen de la Cabeza','Romería celebrada el último fin de semana de abril. Los fieles trasladan la imagen a pie desde la Iglesia Parroquial de Nuestra Señora de la Encarnación hasta su ermita en pleno Parque Natural de la Sierra de María, en un entorno de alta montaña.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('04019','religioso','Iglesia de San Sebastián y Fiestas de los Carretucos','Celebrada las noches del 22 y 23 de enero. Consiste en una de las manifestaciones de piedad popular e (pirofestivas) más singulares del sur de España, donde se arrojan miles de docenas de carretillas (cohetes terrestres) al paso de los santos protectores.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('04092','religioso','Ermita de la Virgen del Socorro. 火','Fiestas patronales del 14 al 16 de septiembre. El día central es el 15 de septiembre, cuando se realiza la bajada y posterior procesión de la imagen, con alfombras de serrín coloreado que cubren las calles principales de la localidad.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('04099','religioso','Iglesia de Nuestra Señora de la Encarnación','Ciclo de Semana Santa (Declarada de Interés Turístico de Andalucía). Destacan los desfiles tradicionales y los solemnes cultos internos de las hermandades tradicionales como los "Esclavos" o los "Cafres", con representaciones de la pasión en la vía pública.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16001','religioso','Santuario de Nuestra Señora de los Santos','Romería multitudinaria celebrada el primer domingo de septiembre. Los romeros acuden al santuario en carrozas engalanadas, a caballo y a pie, destacando la tradicional "subasta de banderas" y la puja por las maniguetas del paso para introducir a la Virgen en su templo.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16003','religioso','Ermita de la Virgencita de la Sierra','Romería celebrada el último domingo de mayo. La imagen de la Virgen es trasladada desde su ermita, ubicada en una de las faldas de la Sierra de Líjar, hasta el centro de la localidad, acompañada de cantos tradicionales y trajes típicos.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16004','religioso','Basílica Menor de Santa María de la Asunción','Festividad de la Virgen de las Nieves el 5 de agosto, precedida por solemnes cultos y procesión por las calles medievales. Destaca también su Semana Santa (Interés Turístico Nacional) y la sobrecogedora procesión del Santísimo Cristo del Romancero.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16009','religioso','Iglesia Conventual de Nuestra Señora del Rosario y Santo Domingo','El 7 de octubre es la festividad principal con una multitudinaria procesión de alabanzas de la Patrona por el casco histórico. En mayo se celebra la festividad de los Milagros de la Virgen, conmemorando la intercesión de la imagen frente a catástrofes naturales.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90032','religioso','Santuario de Nuestra Señora de Regla','El 8 de septiembre se celebra la imponente procesión de la Virgen de Regla, que discurre junto a la misma orilla del mar, congregando a cientos de kilómetros a la redonda a decenas de miles de personas en una de las manifestaciones marianas más multitudinarias del litoral español.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('11020','religioso','Real Basílica de Nuestra Señora de la Merced Coronada y Cartuja de Santa María de la Defensión','Festividad y procesión solemne el 24 de septiembre. Durante la Semana Santa (Interés Turístico Nacional), la ciudad es un gigantesco centro devocional con cofradías de incalculable solera como el "Prendimiento" o el "Nazareno".','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('11022','religioso','Santuario de la Inmaculada Concepción','Festividad grande el 8 de diciembre con una multitudinaria procesión de la patrona. En el mes de julio destaca la procesión marítimo-terrestre de la Virgen del Carmen en el barrio de La Atunara, de hondo fervor marinero.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('11023','religioso','Iglesia Mayor de Santa María la Coronada','Festividad de la Virgen de la Paz el 24 de enero, precedida de una solemne novena. La Semana Santa local cuenta con procesiones de gran sobriedad que recorren el escarpado entramado urbano medieval de la localidad.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('11024','religioso','Santuario de Nuestra Señora de los Remedios','Lunes de Quasimodo (segundo lunes después del Domingo de Resurrección), siendo la romería más antigua de la provincia. Los fieles acuden en carrozas y a caballo al santuario.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('11028','religioso','Priorato e Iglesia de San Sebastián','Festividad de San Sebastián en torno al 20 de enero. Se realiza una procesión del santo desde su templo parroquial y una popular romería en los pinares de Las Canteras, que aúna el culto al santo santero con celebraciones gastronómicas tradicionales.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('11032','religioso','Santuario de Nuestra Señora de la Caridad Coronada','Grandes fiestas patronales en la primera quincena de agosto, culminando el 15 de agosto con la solemne procesión de la Virgen de la Caridad sobre espectaculares alfombras de sal coloreada que cubren las calles del centro histórico.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('11035','religioso','Santuario de Nuestra Señora de la Luz','Primer domingo de septiembre se celebra "La Cabalgata agrícola", donde la Virgen es escoltada a caballo por cientos de jinetes desde su santuario en el campo hasta el pueblo. El último domingo de septiembre se realiza la romería de regreso.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17001','religioso','Iglesia Parroquial de Santa María del Soterraño y Ermita del Calvario','La Semana Santa es el núcleo devocional y cultural, destacando la estación de penitencia de "El Terrible" (Jesús Nazareno) el Viernes Santo por la mañana, con saetas cuarteleras autóctonas. En la víspera del 8 de septiembre se celebra la festividad de la Patrona en su templo excavado en la roca.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17003','religioso','Iglesia de Santa María Mayor y Ermita de la Virgen de Guadalupe','Semana Santa (Declarada de Interés Turístico Nacional). Destaca el ritual sincrético y atávico del toque masivo del tambor por parte de los "coliblancos" y "colinegros", que redoblan de forma ininterrumpida custodiando las sagradas imágenes durante las procesiones.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17006','religioso','Santuario de Nuestra Señora de la Sierra','La célebre "Bajada de la Virgen" se realiza el 4 de septiembre, congregando a decenas de miles de peregrinos a pie que descienden junto a la imagen desde el picacho montañoso. Las fiestas patronales se extienden del 3 al 8 de septiembre, día de su festividad litúrgica con una magna procesión de gala.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('14019','religioso','Iglesia Parroquial de la Asunción y Ermita de la Virgen de la Salud','Feria y fiestas en honor a la Virgen de la Salud a mediados de octubre. Destaca la bajada de la Virgen desde su ermita fluvial hasta el núcleo urbano histórico, acompañada de cantos tradicionales y salvas.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('14021','religioso','Catedral-Mezquita de Córdoba, Basílica de San Pedro e Iglesia del Juramento de San Rafael','El 24 de octubre se celebra la festividad de San Rafael con peregrinaciones urbanas a sus múltiples triunfos e iglesias. Destacan las procesiones de Semana Santa dentro del marco de la Mezquita-Catedral y el masivo besamanos de la Virgen de los Dolores en San Jacinto el Viernes de Dolores.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('14074','religioso','Ermita de la Virgen de Veredas y Auto Sacramental de los Reyes Magos','Romería de la Virgen de Veredas el lunes de Pascua de Pentecostés. Cada cuatro años, a principios de enero, la localidad representa de forma masiva el Auto Sacramental de los Reyes Magos, un drama litúrgico de gran antigüedad.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('14035','religioso','Iglesia de San Juan Bautista (La Catedral de la Sierra) y Ermita de la Virgen de Guía','La Virgen de Guía es trasladada a pie el primer domingo de mayo desde su santuario rural hasta la monumental parroquia urbana, permaneciendo allí para sus cultos mayores antes de ser devuelta en procesión tradicional.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('14038','religioso','Real Santuario de María Santísima de Araceli','Las Fiestas Aracelitanas se celebran el primer domingo de mayo con una multitudinaria procesión procesada a hombros mediante el singular estilo de la "santería" lucentina. La tradicional "Bajada" desde su santuario cupular se realiza el penúltimo domingo de abril, y la "Subida" de retorno tiene lugar el primer domingo de junio.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('14042','religioso','Basílica Pontificia de San Juan de Ávila e Iglesia de Santiago','La fiesta litúrgica de San Juan de Ávila se celebra el 10 de mayo con solemnes cultos y recepciones de peregrinos del clero secular de toda España. En septiembre destaca la Fiesta de la Vendimia, íntimamente ligada al milagroso Cristo de Zacatecas, que procesiona en rogativas agrarias e históricas.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('14055','religioso','Iglesia Parroquial de Nuestra Señora de la Asunción y Ermita de la Aurora','El Viernes Santo se produce la masiva subida a pie de Jesús Nazareno hasta el monte Calvario, donde miles de fieles portan hornazos de pan tradicionales para ser bendecidos por la mano articulada de la imagen. Los sábados de mayo destacan por los cantos nocturnos de los "Hermanos de la Aurora", una de las corporaciones musicales místicas más antiguas de Andalucía.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('14054','religioso','Santuario de la Virgen de la Luna','Romería de la Virgen de la Luna celebrada el domingo de Sexagésima (febrero) para traer la imagen a Pozoblanco, y el lunes de Pentecostés para su regreso al santuario. La Cofradía mantiene un estricto ceremonial de corte militar que incluye salvas continuas de escopetas de avancarga y el baile de la bandera delante de la efigie mariana.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('14058','religioso','Santuario de Nuestra Señora del Carmen','Fiestas patronales en la primera quincena de agosto, culminando la noche del 15 de agosto con la solemne procesión de la Virgen del Carmen, que es vitoreada entre constantes lluvias de pétalos y disparos de pirotecnia por las calles empinadas de la localidad.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('14066','religioso','Ermita de la Virgen de la Estrella','Fiestas patronales del 7 al 10 de septiembre. El día 8 de septiembre se conmemora la aparición milagrosa de la imagen con una procesión solemne, precedida por el traslado procesional de la Virgen desde su ermita rural hasta la parroquia del casco urbano.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19002','religioso','Iglesia Parroquial de la Encarnación y Procesión Marítima','El 15 de agosto se celebra su festividad con una multitudinaria procesión marítimo-terrestre. La Virgen es embarcada en la playa de San Cristóbal y recorre el litoral del municipio escoltada por embarcaciones pesqueras, culminando con un masivo espectáculo pirotécnico desde el castillo de San Miguel.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19001','religioso','Iglesia de la Candelaria y Ermita de los Remedios','El Viernes de Dolores se celebra la fiesta mayor con la solemne procesión de la patrona por las calles del casco antiguo, caracterizada por el silencio y el rezo riguroso del septenario.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18023','religioso','Iglesia Mayor de Nuestra Señora de la Encarnación y Fiesta del Cascamorras','El 6 de septiembre se celebra la Fiesta del Cascamorras (Declarada de Interés Turístico Internacional), un rito de tintes mitológicos y religiosos donde un enviado de la vecina localidad de Guadix intenta llevarse la imagen de la Virgen, siendo perseguido y manchado de pintura negra por miles de bastetanos.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18029','religioso','Hornacina y Cueva Popular del "Santo Santero del Altiplano" (Altar de la fe)','Goteo continuo e informal de peregrinos del Altiplano Granadino cada fin de semana. Los fieles acuden portando exvotos metálicos de extremidades enfermas y botellas de aceite para ser frotadas por las paredes de la cueva-altar popular levantada por la propia comunidad.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18087','religioso','Cripta del Convento de los Padres Capuchinos (Triunfo de Granada)','El día 9 de cada bien mes (y de forma masiva el 9 de febrero, aniversario de su tránsito místico) la cripta se convierte en un colosal hervidero humano. Riadas de decenas de miles de fieles de toda España guardan horas de cola rodeando los jardines del Triunfo para descender a tocar su sepulcro de mármol y cumplir sus promesas de salud.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18089','religioso','Santa Apostólica Iglesia Catedral de Guadix e Iglesia de Santiago','Festividad de San Torcuato el 15 de mayo con traslados y procesión solemne de la reliquia del brazo del santo. El 9 de septiembre se recibe de vuelta al personaje del Cascamorras tras fracasar en su intento de recuperar la Virgen de la Piedad de Baza.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18098','religioso','Santuario de las Santas Alodía y Nunilón de la Sagra e Iglesia de Santa María de la Encarnación','Romería de las Santas el lunes de Pentecostés (Pascuilla). Las imágenes son portadas a pie en un multitudinario traslado procesional desde la monumental iglesia urbana hasta su santuario ubicado a los pies del pico de la Sagra (a más de 1.300 metros de altitud), en un ambiente de hondo recogimiento popular que une a toda la comarca.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18102','religioso','Hornacina Popular del "Santo de Tocón" (Cortijo de la fe)','Goteo continuo e informal de fieles charros y de la Vega de Granada cada fin de semana. Los peregrinos acuden portando exvotos metálicos de extremidades enfermas y prendas textiles para ser frotadas por el altar popular levantado por la propia comunidad.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18116','religioso','Iglesia Parroquial de la Encarnación y Fiesta de San Juan','La noche de San Juan (23 al 24 de junio) se celebra la Carrera del Agua, un multitudinario rito purificador de origen hídrico y religioso donde los asistentes recorren las calles bajo arroyos de agua coincidiendo con las fiestas patronales del santo.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18122','religioso','Iglesia Mayor de la Encarnación y Ermita de Jesús Nazareno','Semana Santa (Declarada de Interés Turístico de Andalucía). El Viernes Santo destaca la sobregogedora procesión de "El Amo", escoltado por los tradicionales "Incisos", figuras encapuchadas que lanzan ancestrales e incómodos cantos satírico-religiosos de origen hispanomusulmán.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18135','religioso','Santuario de Nuestra Señora de los Remedios e Iglesia de la Encarnación','Fiestas patronales del 14 al 16 de agosto, destacando la multitudinaria bajada de la Virgen desde su santuario de la peña rocosa hasta la monumental iglesia circular del centro del pueblo para sus cultos mayores, precedida por promesas tradicionales y marchas silenciosas a pie de los agricultores de la comarca del Poniente Granadino.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18140','religioso','Santuario de Nuestra Señora de la Cabeza','El 15 de agosto se celebra la festividad litúrgica con una procesión multitudinaria por el casco histórico costero, congregando a miles de fieles de la Costa Tropical que acuden a presentar sus promesas al santuario elevado.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18147','religioso','Iglesia de Nuestra Señora de la Expectación y Capilla del Santo Cristo de la Expiración','El Viernes de Dolores se celebra la multitudinaria fiesta del Cristo de la Expiración. La procesión de la imagen destaca por un estruendo ensordecedor continuo debido al disparo masivo de miles de cohetes a lo largo del recorrido como exvoto de los peregrinos.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22002','religioso','Santuario de Nuestra Señora del Rocío (Ermita del Rocío) e Iglesia Parroquial de la Asunción','Romería de El Rocío durante el fin de semana de Pentecostés, con el célebre "salto de la reja" la madrugada del lunes. Cada siete años se realiza "La Venida", traslado a pie de la Virgen durante la noche a lo largo de 15 kilómetros hasta el pueblo de Almonte, donde permanece nueve meses antes de regresar en el "Rocío Chico" (agosto).','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22001','religioso','Ermita de la Mezquita y Fiestas de las Cruces de Mayo','Celebrada el primer fin de semana de mayo. Consiste en un ancestral rito de rivalidad mística e identitaria entre la Cruz de la Fuente y la Cruz del Llano, caracterizado por el canto de fandangos tradicionales, el desfile de las "mayas" con trajes típicos y la solemne procesión hacia el templo de la colina.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22005','religioso','Ermita de San Mamés (Yacimiento de Turobriga) y Ermita de la Virgen de la Lapa','Romería de San Mamés el último fin de semana de mayo. Los romeros se desplazan a caballo y a pie vestidos con atuendos camperos hasta los llanos de la antigua ciudad romana para celebrar los cultos solemnes y el baile de las banderas.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21025','religioso','Ermita de Nuestra Señora de la Piedad','Fiestas patronales del 7 al 11 de septiembre. El día central es el 8 de septiembre, cuando se procesiona la efigie mariana desde su ermita serrana por el entramado urbano medieval bajo el repique manual de las campanas mudéjares.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21041','religioso','Santuario de Nuestra Señora de la Cinta','Fiestas grandes en torno al 8 de septiembre. A finales de agosto se realiza la tradicional "Bajada" de la Virgen desde su santuario cupular en el cabezo hasta la Catedral de la Merced, realizándose la procesión de gloria el 8 de septiembre y la "Subida" de regreso el día posterior.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21050','religioso','Monasterio de Santa Clara y Ermita de Montemayor','Romería de la Virgen de Montemayor el segundo fin de semana de mayo, congregando a miles de peregrinos en los pinares que rodean el santuario. En septiembre se celebran los "Días de la Virgen" con procesiones solemnes por el núcleo urbano.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21055','religioso','Monasterio de Santa María de la Rábida y Ermita de la Virgen de los Milagros','Romería de la Virgen de los Milagros el último fin de semana de agosto. La imagen es trasladada a hombros desde la Iglesia de San Jorge hasta el paraje del monasterio franciscano. El 15 de agosto se celebra su procesión de gloria y festividad litúrgica.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21058','religioso','Santuario de la Virgen de la Peña','Romería de la Virgen de la Peña el último fin de semana de abril, calificada como una de las más puras y antiguas del Andévalo. Destaca el ritual de "La Danza de las Espadas", rito coreográfico-religioso ancestral ejecutado por varones delante del paso de la Virgen.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21070','religioso','Iglesia de San Antonio Abad','Festividad el último fin de semana de enero. La procesión del santo dura más de 30 horas consecutivas de forma ininterrumpida, recorriendo todas las casas del pueblo mientras los vecinos realizan las famosas "tiradas" (arrojando desde los balcones panes, jamones y alimentos al paso del santo).','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24003','religioso','Iglesia de Santa María la Mayor y la Ruta Mística de Santo Manuel hacia Ventas del Carrizal','Goteo diario e ininterrumpido de fieles que realizan la ruta espiritual a pie desde el núcleo de Alcaudete hasta el paraje de Ventas del Carrizal, recreando el camino de sanación del santo popular. Su punto álgido devocional ocurre durante la primavera, coincidiendo con las rogativas tradicionales del olivar.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24005','religioso','Real Basílica y Santuario de Nuestra Señora de la Cabeza','Justificación de Rango: Se eleva al Top 10 Absoluto de España. Es la romería documentada más antigua del país (1227). Moviliza anualmente a más de medio millón de peregrinos en el cerro del Cabezo (Sierra Morena). Cuenta con más de 80 cofradías filiales en España y América. Es el único santuario de Andalucía con la distinción pontificia de la Rosa de Oro (otorgada por Benedicto XVI en 2009) y rango de Basílica Menor, equiparándola teológicamente a los grandes centros mundiales. ANEXO: Catálogo de Santos Populares, Taumaturgos y Devociones de Masas Omitidas.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24010','religioso','Santuario de Nuestra Señora del Rosel y del Santo Cristo de la Yedra','Romería de la Yedra celebrada en torno al 8 de septiembre. Desplazamiento masivo a pie de miles de fieles desde las ciudades monumentales de Úbeda y Baeza a través de los viejos caminos de olivar. Destaca el ancestral rito del canto de las vísperas tradicionales y las promesas que se cumplen portando pesadas velas exvoto tras el paso.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23028','religioso','Iglesia Parroquial de Santa María y Ermita de la Virgen de la Cabeza','Las fiestas patronales se celebran del 14 al 20 de septiembre. El acto central es la procesión nocturna del Cristo del Consuelo el 17 de septiembre, caracterizada por la espectacular "Entrada del Trigo", donde los fieles portan espigas y realizan ofrendas agrícolas ancestrales.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23050','religioso','Santuario de Nuestra Señora de la Merced (Iglesia del Sagrario de la Catedral)','La madrugada del Viernes Santo se produce la imponente procesión de "El Abuelo", la mayor manifestación de fe urbana de la provincia. Más de 100.000 personas saturan el casco histórico; el Nazareno avanza bajo un mar de saetas e intercesiones de promesas descalzas que caminan tras su estela durante más de diez horas.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23051','religioso','Iglesia Parroquial de la Natividad de Nuestra Señora','Fiestas patronales del 14 al 16 de septiembre. La noche del 14 de septiembre se realiza la solemne procesión de Jesús Nazareno, que congrega a miles de devotos que realizan el recorrido descalzos o portando pesadas cadenas en cumplimiento de promesas penitenciales.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23055','religioso','Santuario de Nuestra Señora de Linarejos','Las fiestas patronales se concentran en torno al 5 de agosto (festividad litúrgica) y las tradicionales fiestas votivas de Pentecostés. Destacan las marchas a pie y las constantes peregrinaciones de los barrios obreros mineros hacia el santuario.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23060','religioso','Santuario de Santa María de la Villa e Iglesia de la Virgen de la Villa','El martes de Pentecostés se celebra la fiesta mayor con la bajada y posterior procesión de la efigie mariana por el escarpado casco histórico, acompañada de ritos de ofrendas de las cooperativas olivareras de la comarca.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23075','religioso','Altar de Promesas de la Marines y la Ruta Santera del Guadalimar','Peregrinación y cultos espontáneos durante la primera quincena de mayo y finales de agosto. Los files y jornaleros de la comarca de La Loma acuden a pie por las veredas agrarias para encender hachones exvoto ante una hornacina rústica levantada de forma comunitaria.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23092','religioso','Sacra Capilla del Salvador, Basílica de Santa María de los Reales Alcázares y Santuario de la Virgen de Guadalupe','El 1 de mayo se celebra la populosa "Romería de la Virgen de Guadalupe", trasladando la imagen desde su santuario rural del Gavellar hasta la ciudad. El 8 de septiembre procesiona de forma solemne. El 14 de diciembre destaca la solemne conmemoración del tránsito místico de San Juan de la Cruz en su convento-museo.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23095','religioso','Iglesia Parroquial de la Asunción y Procesión del Corpus Christi','Festividad del Corpus Christi (Declarada de Interés Turístico de Andalucía). Destaca por la confección comunitaria de alfombras efímeras de serrín coloreado y espectaculares altares que cubren la totalidad del casco histórico para el paso de la fastuosa custodia plateresca.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('32025','religioso','Iglesia Parroquial de Nuestra Señora de la Encarnación y Ermita de las Flores','El Viernes Santo por la mañana se celebra "La Despedida" (Declarada de Interés Turístico Nacional de Andalucía), un sobrecogedor acto litúrgico donde los tronos de Jesús Nazareno y la Virgen de los Dolores se aproximan hasta saludarse mediante tres reverencias coordinadas. El domingo posterior al 8 de septiembre se celebra la Romería de la Virgen de las Flores desde su ermita rural.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('32002','religioso','Real Colegiata de Santa María la Mayor, Iglesia de los Remedios y Convento de la Madre de Dios','Festividad de la Virgen de los Remedios el 8 de septiembre. Durante la Semana Santa destaca la arraigada tradición de "correr la vega", un rito donde los hermanacos portan los pesados tronos a gran velocidad por las empinadas cuestas de la ciudad hasta los templos para bendecir las tierras agrícolas.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('32003','religioso','Santuario de la Virgen de Gracia','La noche del 14 al 15 de agosto se celebra la multitudinaria romería nocturna al santuario. Miles de fieles ascienden a pie la sinuosa carretera de la sierra iluminados con antorchas y velas, culminando con solemnes misas de alba y la procesión perimetral de la imagen mariana.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29067','religioso','Santa Iglesia Catedral de la Encarnación, Basílica del Real Santuario de la Victoria e Iglesia de San Lázaro','Festividad de la Virgen de la Victoria el 8 de septiembre con procesión solemne desde la catedral. Su Semana Santa (Declarada de Interés Turístico Internacional) destaca por las colosales dimensiones de sus tronos, el desfile militar de la Legión escoltando al Cristo de la Buena Muerte y el masivo traslado del Cautivo por el barrio de la Trinidad.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29080','religioso','Iglesia Parroquial de San Pedro Apóstol y Ermita de Nuestra Señora de la Fuensanta','Bajada de la Virgen desde su ermita el 12 de agosto. La festividad principal ocurre el 15 de agosto con la singular procesión de "La Rifa", donde los devotos pujan económicamente a viva voz en plena calle para tener el derecho de portar los varales del trono.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29084','religioso','Iglesia de Santa María la Mayor, Santuario de la Virgen de la Paz y Convento de la Merced','Festividad de la Virgen de la Paz el segundo domingo de mayo con una solemne procesión tradicional. Peregrinaciones continuas de fieles y comunidades religiosas al Convento de las Carmelitas Descalzas para venerar la reliquia teresiana.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29094','religioso','Ermita de Nuestra Señora de los Remedios (Cerro de San Cristóbal)','Fiestas patronales en la segunda quincena de noviembre. Destaca la tradicional bajada de la Virgen desde su santuario cupular hasta la Iglesia de San Juan Bautista para la celebración de su novena, congregando a miles de fieles de la Axarquía.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29100','religioso','Ermita de Nuestra Señora del Portón y Fiesta del Santo Cristo de la Cruz del Pobre','Romería y procesión solemne el 3 de mayo (Día de la Cruz). Los vecinos levantan altares efímeros de flores y ramas en los rincones del pueblo, procesionando al Cristo en un ambiente de recogimiento rural y promesas agrícolas.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40002','religioso','Santuario de Nuestra Señora del Águila','La festividad principal se celebra el 15 de agosto con una solemne procesión triunfal de la Virgen por los alrededores de la antigua fortaleza medieval. En la víspera, miles de fieles participan en la tradicional marcha y subida a pie al cerro del Castillo.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41023','religioso','Iglesia Parroquial de Nuestra Señora de la Asunción y Ermita de la Divina Pastora','Fenómeno antropológico único de rivalidad devocional. El 15 de agosto se celebra la procesión de la Asunción, destacando el rito de la "Subida" en septiembre. Por su parte, la Divina Pastora procesiona el 8 de septiembre, viviendo su punto álgido con la "Fiesta de la Pastora" y la multitudinaria Romería a la aldea de Los Pajares el último fin de semana de septiembre.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41024','religioso','Iglesia de Santa María de la Asunción y Santuario de la Virgen de Gracia','Las fiestas patronales se desarrollan del 8 al 16 de septiembre con una multitudinaria novena. Cada cinco años se realiza la histórica "Bajada" extraordinaria de la Virgen desde su santuario de la dehesa hasta la Iglesia Mayor del centro urbano, congregando a miles de fieles a pie.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41038','religioso','Ermita de Nuestra Señora de Valme y Parroquia de Santa María de la Magdalena','Romería de Valme, celebrada el tercer domingo de octubre (Declarada de Interés Turístico Nacional). Centenas de miles de peregrinos escoltan a la Virgen en carretas cubiertas de flores de papel rizadas a mano desde Dos Hermanas hasta su ermita en el Cortijo de Cuarto.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41039','religioso','Iglesia Mayor de Santa Cruz e Iglesia de Santiago','Festividad de la Virgen del Valle el 8 de septiembre con una procesión solemne que congrega a las hermandades de la comarca. La Semana Santa de Écija destaca por el empaque de sus cofradías barrocas y el tradicional volteo manual de campanas desde sus famosas torres ecijanas.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41053','religioso','Iglesia Parroquial de Nuestra Señora de la Oliva y Ermita del Castillo','Festividad de la Virgen del Castillo el 12 de septiembre, precedida por una multitudinaria bajada desde su ermita fortificada. Destaca también la festividad de la Virgen de la Oliva el 15 de agosto por las calles del centro histórico.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41055','religioso','Santuario de Nuestra Señora de Setefilla','Romería el 8 de septiembre al santuario serrano. Las "Venidas" de la Virgen al pueblo no tienen fecha fija; se deciden de forma comunitaria por motivos de necesidad agraria o salud, realizándose un sobregogedor traslado a hombros donde los devotos corren con el paso envuelto en una densa nube de polvo.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41060','religioso','Iglesia Parroquial de San Juan Bautista e Iglesia de Santa María de la Mota','Semana Santa (Declarada de Interés Turístico Nacional de Andalucía). Destaca la mañana del Viernes Santo con el "Mandato" y los antiquísimos cantos de las "Saetas de Marchena" (moleeras y de pascua), ejecutadas de forma primitiva y monódica ante los pasos.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41068','religioso','Insigne Iglesia Colegial de Nuestra Señora de la Asunción y Monasterio de la Encarnación','Fiestas patronales en honor a la Virgen de los Reyes en septiembre. Su Semana Santa destaca por el sobregogedor recogimiento y sobriedad de cofradías como la del Cristo de la Misericordia (talla de Juan de Mesa de 1623) procesionada en silencio absoluto.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41091','religioso','Santa, Metropolitana y Patriarcal Iglesia Catedral de Santa María de la Sede; Basílica de la Macarena; Basílica del Gran Poder; Capilla de los Marineros; Basílica de María Auxiliadora','La Semana Santa (Interés Turístico Internacional) es el culmen de la piedad popular urbana europea, con la mítica "Madrugá" como epicentro. El 15 de agosto se realiza la multitudinaria procesión claustral-terrestre de la Virgen de los Reyes, que congrega a millares de fieles de toda Andalucía desde el alba. El 23 de noviembre y el 30 de mayo se abre la urna de plata del rey San Fernando en la Capilla Real para la veneración de su cuerpo incorrupto. El Corpus Christi destaca por su fastuosa procesión litúrgica con el baile de los Seises en el altar mayor de la Catedral.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41092','religioso','Iglesia Parroquial de San Vicente Mártir y Ermita de Nuestra Señora de la Soledad','Función Principal y procesión solemne el 14 de septiembre (Exaltación de la Santa Cruz). El Señor de Tocina es procesionado rodeado de miles de velas exvoto y promesas en silencio que caminan descalzas tras el paso por las calles de la Vega del Guadalquivir.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41094','religioso','Iglesia Parroquial de Nuestra Señora de la Consolación (Palacio Arzobispal)','Fiestas patronales en torno al 8 de septiembre en honor a la Virgen de la Consolación. Destaca la salida de la hermandad del Rocío de Umbrete en Pentecostés, una de las de mayor solera y antigüedad del Aljarafe, arrastrando masivas comitivas de carretas tradicionales.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41095','religioso','Santuario de Nuestra Señora de la Consolación e Iglesia de Santa María de la Mesa','Festividad de la Virgen el 8 de septiembre. Durante la víspera y la madrugada se realiza la antiquísima peregrinación a pie desde Sevilla capital, Dos Hermanas, Los Palacios y toda la Campiña sevillana, sumando decenas de miles de romeros que acceden al santuario con velas y promesas descalzas.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90272','religioso','Colegiata de Santa María la Mayor','Romerías estacionales de las gentes del Somontano y procesión solemne del Santo Cristo de Alquézar en septiembre. Destacan los ritos de rogativas históricas en su majestuoso claustro románico para la protección de los viñedos y cultivos frente a los rayos y el granizo.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22048','religioso','Catedral de Santa María de la Asunción y Monasterio de Nuestra Señora del Pueyo','Fiestas de San Ramón del 20 al 23 de junio con el tradicional encendido de las "hogueras de San Ramón". Peregrinaciones constantes de carácter nacional e internacional al Museo de los Mártires Claretianos durante todo el año, especialmente en el aniversario de su ejecución en agosto.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22117','religioso','Basílica de la Virgen de la Peña y Parroquia de San Miguel','Fiestas Patronales del 12 al 15 de septiembre (Declaradas de Interés Turístico Nacional). Destacan los ancestrales bailes tradicionales (las espadas y las cintas), la "mojiganga" satírico-religiosa y el canto de las "Albadas" nocturnas ante la imagen del Santo Cristo.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22130','religioso','Santa Iglesia Catedral de San Pedro de Jaca y Real Monasterio de Benedictinas','Festividad de Santa Orosia el 25 de junio. Confluyen en la Catedral las romerías de los pueblos de la montaña portando las "cruces parroquiales". Históricamente era el epicentro de los rituales de curación de "endemoniados" y personas con afecciones mentales bajo la intercesión directa de la reliquia.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22149','religioso','Castillo de Loarre e Iglesia de San Esteban','Festividad de San Demetrio el 8 de octubre, con solemnes cultos litúrgicos y procesión de la arqueta de las reliquias. Romerías primaverales tradicionales desde las localidades vecinas de la Hoya de Huesca hacia la capilla fortificada.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22158','religioso','Catedral de Santa María del Romeral y Ermita de la Virgen de la Alegría','Romería de la Virgen de la Alegría el Lunes de Pascuillas (segundo lunes de Pascua de Resurrección). Miles de peregrinos ascienden a pie el cerro donde se ubica el santuario, entonando cantos tradicionales y realizando comidas camperas de hermandad.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22214','religioso','Santuario de Torreciudad (Nuevo y Viejo)','Peregrinación continua a lo largo de todo el año, con un pico de asistencia masiva durante la Jornada Mariana de la Familia en septiembre. Jornadas de oración, confesiones multitudinarias y la tradicional procesión de la Virgen románica por la explanada del complejo.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22252','religioso','Ermitas de las Cuevas de Santa Orosia','Romería de Santa Orosia el 25 de junio. Los peregrinos ascienden a pie el escarpado sendero del monte, jalonado por ocho ermitas singulares, portando el relicario con la cabeza de la santa. Destaca el ancestral "Dance de Yebra", ejecutado con palos, pañuelos y al son del chiflo y el salterio pirenaico.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('43002','religioso','Iglesia de Santa María la Mayor','Celebración de la Semana Santa (perteneciente a la Ruta del Tambor y el Bombo, Declarada de Interés Turístico Internacional). Destaca la procesión del "Sellado del Sepulcro" el Sábado Santo y el ensordecedor "Romper la Hora". El 9 de septiembre se realiza la romería al Santuario de la Virgen de los Pueyos.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44025','religioso','Ermita de San Macario e Iglesia Parroquial de la Natividad','Semana Santa integrada en la Ruta del Tambor y el Bombo. El Jueves Santo a medianoche se realiza la multitudinaria subida a pie tocando el tambor hasta el Santuario de San Macario, iluminando el monte con antorchas. El tercer domingo de septiembre es la fiesta mayor del santo.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44051','religioso','Templo del Pilar (Capilla del Milagro) e Iglesia Parroquial de la Esperanza','El 29 de marzo se conmemora de forma solemne el Milagro de la Restitución de la Pierna. Durante la Semana Santa, el Viernes Santo a las 12:00 del mediodía se celebra la monumental y mundialmente conocida "Rompida de la Hora", donde miles de bombos tiñen el municipio de color morado penitencial.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44149','religioso','Convento de las Agustinas Ermitañas (San Julián y Santa Lucía)','Festividad de Santa Lucía y San Julián con procesiones de gran recogimiento que recorren el recinto amurallado medieval. Cantos de auroros tradicionales interpretados por cofrades masculinos durante la madrugada de las festividades litúrgicas.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44216','religioso','Santa Iglesia Catedral de Santa María de Mediavilla e Iglesia de San Pedro','Celebraciones del Corpus Christi y la festividad de los Mártires Franciscanos. Durante el ciclo pascual destacan las procesiones del Santo Entierro, integrando ritos del mudéjar y toques de oración sobrios.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50297','religioso','Catedral-Basílica de Nuestra Señora del Pilar, Catedral de San Salvador (La Seo) e Iglesia Parroquial de San Pablo','Las Fiestas del Pilar se celebran en torno al 12 de octubre, destacando la monumental Ofrenda de Flores (que congrega a cientos de miles de oferentes con trajes tradicionales), la Ofrenda de Frutos y el Rosario de Cristal (procesión barroca de faroles de vidrio única en el mundo). El 2 de enero se conmemora solemnemente la Venida de la Virgen. El 29 de enero se celebra San Valero con el reparto tradicional de roscón bendecido y la apertura de su relicario.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90148','religioso','Ermita de Nuestra Señora de los Palacios','Romería tradicional el primer domingo de mayo y fiestas mayores en septiembre. Los devotos suben a pie hasta el templo serrano entonando coplas tradicionales aragonesas y portando velas en cumplimiento de promesas familiares.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90158','religioso','Iglesia Parroquial de Santa María y Ermita de San Blas','Festividad de San Blas el 3 de febrero. Se celebra el rito ancestral de "El Máscaro", un personaje folclóricoreligioso que es perseguido por los niños mientras le lanzan manzanas, terminando con la subida al cerro del santo para la bendición de alimentos y las tradicionales roscas de San Blas.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50074','religioso','Colegiata de Santa María Mayor del Pilar y Ermita de la Balma','Conmemoración histórica y litúrgica del Compromiso de Caspe a finales de junio. Procesión solemne de la Reliquia de la Veracruz el 1 de mayo y durante las fiestas de San Roque en agosto, con gran participación de las cofradías de la comarca del Bajo Aragón-Caspe.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50067','religioso','Real Colegiata del Santo Sepulcro y Santuario de la Virgen de la Peña','Fiestas de la Virgen de la Peña del 5 al 9 de septiembre, con una multitudinaria procesión del Rosario de Cristal por las empinadas calles de origen islámico. La Semana Santa de Calatayud (Interés Turístico de Aragón) destaca por su antiquísima procesión del Santo Entierro, donde desfilan personajes bíblicos vivientes.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50094','religioso','Basílica de Santa María de los Sagrados Corporales','La festividad del Corpus Christi es el eje absoluto del municipio (Declarada de Interés Turístico de Aragón). Se realiza la solemne procesión de los Sagrados Corporales portados en una custodia de oro bajo una lluvia de pétalos, subiendo hasta la Torreta de los Campamentos para bendecir los campos de la comarca.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50192','religioso','Monasterio de Piedra (Monasterio de Santa María de la Defensión)','Peregrinación continua de turismo cultural y religioso a lo largo de todo el año. Celebración de misas solemnes en las ruinas de la abadía gótica durante las festividades cistercienses y romerías locales de los pueblos circundantes del valle del río Piedra.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50251','religioso','Catedral de Nuestra Señora de la Huerta y Monasterio de Santa María de Veruela (en las cercanías del Moncayo)','Fiestas de San Atilano del 27 de agosto al 1 de septiembre, que comienzan con el tradicional rito del "Cipotegato". Romerías de los pueblos del Moncayo al Monasterio de Veruela y procesiones claustrales en honor a la Virgen del Moncayo.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05005','religioso','Santuario de Nuestra Señora de Covadonga (Santa Cueva y Basílica de Santa María la Real)','El Día de Asturias (8 de septiembre) es la festividad máxima, congregando a decenas de miles de peregrinos que ascienden a pie desde toda la región. Destacan las procesiones claustrales, el canto del Himno a la Virgen de Covadonga y las marchas penitenciales nocturnas de portadores de antorchas.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33036','religioso','Basílica de Santa María de la Asunción de Llanes y Ermita de la Virgen de la Guía','Fiestas de la Virgen de la Guía (7 y 8 de septiembre) y San Roque (16 de agosto), caracterizadas por una fortísima rivalidad devocional y folclórica entre bandos locales. Destacan las procesiones nocturnas con antorchas, el disparo masivo de pirotecnia marítima y el baile del Pericote interpretado por cofrades con trajes tradicionales de llanisca.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33044','religioso','Santa Iglesia Catedral Basílica Metropolitana de San Salvador y la Cámara Santa','El Santo Sudario se expone públicamente solo tres veces al año: el Viernes Santo, el 14 de septiembre (Exaltación de la Santa Cruz) y el 21 de septiembre (San Mateo), atrayendo a peregrinos de todo el mundo. El 21 de septiembre culmina el tradicional "Jubileo de la Santa Cruz" (La Perdonanza). El 10 de diciembre se celebran solemnemente las fiestas de Santa Eulalia con procesión y veneración de su arqueta de plata.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05006','religioso','Monasterio de San Juan Bautista de Corias (El Escorial Asturiano) y Capilla del Carmen','La Descarga del Carmen se celebra el 16 de julio (Declarada de Interés Turístico de Asturias). Al paso de la Virgen por el puente romano, la Sociedad de Artesanos dispara de forma masiva y simultánea miles de voladores (cohetes) en apenas siete minutos, provocando un estruendo ensordecedor que cubre el valle de humo blanco como ofrenda de fe.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33059','religioso','Colegiata de Santa María la Mayor','Fiestas patronales y solemnes cultos en honor a la Virgen del Viso en mayo, con romería tradicional que asciende al monte homónimo. Durante todo el año registra un goteo constante de peregrinos del Camino de Santiago Primitivo que sellan sus credenciales ante el sepulcro monumental.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90654','religioso','Santuario de Santa María de Lluc (Monasterio de Lluc)','La noche del primer sábado de agosto se celebra la multitudinaria marcha "Des Güell a Lluc a peu", donde decenas de miles de peregrinos caminan más de 45 kilómetros desde Palma hasta el santuario en plena Sierra de Tramuntana. El 10 de agosto se conmemora de forma solemne la festividad litúrgica con el canto de la Escolania de Lluc ("Els Blauets"), uno de los coros de niños cantores más antiguos de Europa.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('07040','religioso','Catedral de Santa María de Palma (La Seu), Basílica de San Francisco e Iglesia de San Miguel','Fiestas en honor a Santa Catalina Tomàs el tercer sábado de octubre, con el desfile del "Carro Triunfal de la Beateta" por las avenidas medievales. Destaca también la solemne liturgia y canto del Sibil·la en la Catedral la noche de Navidad (Patrimonio Inmaterial de la Humanidad).','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('07063','religioso','Real Cartuja de Valldemossa e Iglesia Parroquial de San Bartolomé','Festividad de las Reliquias de "La Beateta" el 28 de julio, caracterizada por procesiones populares de gran pureza formal donde los niños visten trajes tradicionales de payés para escoltar a la santa por las calles empedradas cubiertas de macetas de flores.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90778','religioso','Basílica Real de Nuestra Señora de la Candelaria (Santuario de la Candelaria)','La noche del 14 al 15 de agosto se celebra la monumental Caminata a Candelaria, donde decenas de miles de peregrinos caminan a pie desde todos los puntos de la isla de Tenerife cruzando las montañas. El 15 de agosto destaca la solemne misa y la procesión. El 2 de febrero se celebra la Fiesta de las Candelas con una procesión nocturna iluminada exclusivamente con velas exvoto.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('38023','religioso','Santa Iglesia Catedral de Nuestra Señora de los Remedios, Real Santuario del Santísimo Cristo de La Laguna e Iglesia del Convento de Santa Catalina de Siena','Fiestas del Santísimo Cristo de La Laguna durante el mes de septiembre, destacando la procesión de las antorchas y los fuegos artificiales la noche del 14 de septiembre. El 15 de febrero se abre el sarcófago de Sor María de Jesús en el convento de dominicas, atrayendo a riadas masivas de miles de files de toda Canarias que guardan horas de cola para tocar el cuerpo incorrupto.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('38010','religioso','Santuario del Santísimo Cristo de la Resignación e Iglesia de Santiago Apóstol','El 3 de mayo se celebra la festividad de las Cruces y Fuegos (Declarada de Interés Turístico Nacional), un ancestral rito de rivalidad mística entre las calles de El Medio y El Sol, que engalanan centenares de cruces efímeras de flores y realizan el mayor espectáculo de pirotecnia de Canarias durante las procesiones.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('35027','religioso','Basílica de Nuestra Señora del Pino','La noche del 7 al 8 de septiembre se realiza la tradicional e imponente marcha a pie hasta la villa mariana, donde decenas de miles de romeros de todas las islas caminan cruzando los barrancos. El 8 de septiembre destaca la fastuosa Romería-Ofrenda, en la que cada municipio de la isla acude en carretas tradicionales engalanadas con productos agrícolas y folclore local.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('35016','religioso','Santa Iglesia Catedral-Basílica de Santa Ana y Ermita de San Antonio Abad','Festividad del Corpus Christi con monumentales alfombras de flores y arenas coloreadas cubriendo el centro histórico de Vegueta. En las vísperas de San Juan (24 de junio) se realizan solemnes liturgias fundacionales y traslados tradicionales.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('35023','religioso','Iglesia de Santa María de Guía y Fiesta de Las Marías','Fiesta votiva de Las Marías, celebrada el tercer domingo de septiembre. Se caracteriza por la bajada de las ramas desde el monte de los altos del municipio y el desfile de carretas tradicionales, bajo el sonido ancestral de las caracolas de mar (bucios) sopladas por los fieles en acción de gracias.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39015','religioso','Monasterio de Santo Toribio de Liébana','Celebración del Año Jubilar Lebaniego (Año Santo) cada vez que el 16 de abril (festividad de Santo Toribio) cae en domingo, procediéndose a la apertura solemne de la Puerta del Perdón. Peregrinación continua a través del Camino Lebaniego. El 2 de mayo destaca la antiquísima bajada de la Virgen de la Salud desde los Picos de Europa hasta el cenobio.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39080','religioso','Iglesia de Santa María de los Ángeles y Santuario de la Virgen de la Barquera','Fiesta de La Folía, celebrada el segundo domingo después de Pascua de Resurrección (Declarada de Interés Turístico Nacional). Destaca la imponente procesión marítima donde la Virgen es embarcada y escoltada por toda la flota pesquera en alta mar, acompañada de cantos tradicionales de picayos e instrumentos de percusión.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39076','religioso','Colegiata de Santa Juliana','Festividad de Santa Juliana el 28 de junio con solemnes cultos y procesión de las reliquias por las calles empedradas medievales. Registra un flujo masivo de peregrinos del Camino de Santiago del Norte que pernoctan en la villa y rinden culto a la patrona en el altar mayor de la colegiata.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90243','religioso','Santuario de Nuestra Señora de la Bien Aparecida','La festividad máxima se celebra el 15 de septiembre, atrayendo a decenas de miles de peregrinos de toda Cantabria y provincias limítrofes como Vizcaya y Burgos. Destacan las marchas a pie subiendo los 15 kilómetros de curvas desde los valles bajos y el tradicional rezo del Viacrucis de montaña jalonado por monumentos pétreos.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39038','religioso','Iglesia Parroquial de San Pedro e Iglesia del Santo Cristo de la Agonía','Fiestas patronales y solemnes cultos del 14 al 18 de septiembre, coincidiendo con la Exaltación de la Santa Cruz. Atrae peregrinaciones organizadas de cofradías y fieles de carácter nacional e internacional durante todo el año, quienes asisten a las misas devocionales y realizan horas de oración contemplativa frente a la efigie.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39075','religioso','Santa Iglesia Catedral Basílica de la Asunción de la Virgen y la Cripta de la Iglesia Alta (Parroquia del Cristo)','Festividad de los Santos Mártires el 30 de agosto, precedida por el traslado procesional de las reliquias de las santas cabezas desde la cripta baja por las avenidas de la bahía. Recibe un goteo continuo de peregrinos del Camino de Santiago del Norte y del Camino Lebaniego.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('51025','religioso','Iglesia-Convento de Santa Teresa de Jesús (Casa Natal), Monasterio de la Encarnación y Real Monasterio de Santo Tomás','Fiestas Patronales en honor a Santa Teresa del 8 al 15 de octubre. El día central (15 de octubre) destaca por la magna procesión de la imagen de la santa mística por el recinto amurallado, con la asistencia de órdenes religiosas de todo el mundo. Durante todo el año, la ciudad es un punto de peregrinación de masas integrado en la ruta internacional "Huellas de Teresa".','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('51001','religioso','Santuario de San Pedro de Alcántara','Festividad de San Pedro de Alcántara el 19 de octubre. Congrega a millares de fieles de toda Extremadura, Madrid y Castilla y León, quienes realizan peregrinaciones a pie a través del Valle del Tiétar hasta el santuario rural para venerar su sepulcro.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05074','religioso','Iglesia-Convento de San Juan de la Cruz y Parroquia de San Cipriano','Fiestas en honor a San Juan de la Cruz en torno al 14 de diciembre (festividad litúrgica). Se desarrollan vigilias místicas de poesía sacra, congresos de teología y procesiones austeras con reliquias del santo que atraen a estudiosos del misticismo y peregrinos de diversos continentes.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('51003','religioso','Ermita del Santísimo Cristo del Caño e Iglesia de la Asunción de Nuestra Señora','Romería del Cristo del Caño el primer domingo de septiembre, con una procesión multitudinaria de la efigie que cruza el puente románico sobre el río Tormes, acompañada por subastas tradicionales de banzos y ofrendas agrícolas de la comarca.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05114','religioso','Monasterio de Nuestra Señora de Gracia (Palacio Real de Juan II) e Iglesia de San Nicolás de Bari','Fiestas patronales del Santísimo Cristo de las Injurias a mediados de septiembre, destacando la solemne procesión de la imagen bajomedieval por el recinto amurallado. Goteo constante de investigadores y grupos de fe vinculados a la causa de beatificación de Isabel la Católica.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05201','religioso','Ermita de San Antonio Abad e Iglesia Parroquial de San Bartolomé','Celebración de las "Luminarias de San Bartolomé" la noche del 16 de enero (víspera de San Antón). Consiste en un ancestral rito piadoso donde los jinetes locales cruzan a caballo monumentales hogueras de humo verde dispuestas por las calles para purificar y bendecir a las bestias.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05241','religioso','Monasterio de los Jerónimos de Guisando','Romerías estacionales tradicionales de las gentes del Alberche y visitas litúrgico-culturales organizadas a las ruinas consolidadas del monasterio y sus cuevas exvoto eremíticas.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09003','religioso','Santa Iglesia Catedral Basílica Metropolitana de Santa María y la Capilla del Santo Cristo de Burgos','Festividad de San Lesmes el domingo más cercano al 30 de enero, con reparto de panecillos bendecidos y bailes tradicionales de gigantones. Durante las fiestas de San Pedro y San Pablo (junio) destaca la monumental ofrenda de flores a Santa María la Mayor. El Santo Cristo es objeto de peregrinaciones continuas y solemnes cultos durante todo el año por parte de fieles de la ruta jacobea.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09084','religioso','Ermita de Santa Lucía y Necrópolis de las Eras','Romería tradicional en honor a Santa Lucía el domingo siguiente al 13 de diciembre. Los devotos de la comarca de la Sierra de la Demanda suben al cerro, se ungen los ojos con el agua bendecida de la ermita y realizan subastas de roscos tradicionales.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09011','religioso','Monasterio de San Salvador de Oña','Festividad de San Íñigo el 1 de junio, con solemnes cultos y procesión de su arqueta-relicario barroca. En agosto se escenifica en el interior de la abadía el drama histórico-religioso "El Cronicón de Oña", donde los vecinos conmemoran los orígenes místicos del cenobio.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09018','religioso','Abadía de Santo Domingo de Silos (Monasterio Benedictino)','Peregrinación mística continua durante todo el año. Los files acuden de forma masiva a las Oficinas Litúrgicas (Laudes, Vísperas y Completas) para escuchar el canto gregoriano interpretado en directo por los monjes. Festividad mayor el 20 de diciembre.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09044','religioso','Monasterio de San Juan de Ortega','Festividad de San Juan de Ortega el 2 de junio con la romería de los pueblos de la comarca portando sus cruces parroquiales. Los momentos álgidos del turismo de fe ocurren en los equinoccios de primavera y otoño (21 de marzo y 23 de septiembre), cuando miles de fieles acuden a presenciar en silencio el "Milagro de la Luz".','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26010','religioso','Santa Iglesia Catedral Basílica de Santa María de la Regla, Real Colegiata Basílica de San Isidoro y Santuario de la Virgen del Camino (en los accesos metropolitanos)','La festividad de San Froilán (5 de octubre) es la gran romería de la provincia; miles de devotos se desplazan al Santuario de la Virgen del Camino portando carros engalanados y pendones leoneses kilométricos para cumplir el rito de "tirarle de la nariz al santo" en la puerta del templo. El 26 de abril se celebra la ancestral ceremonia de "Las Cabezadas" en San Isidoro, un litigio político-religioso medieval donde el ayuntamiento y el cabildo debaten de forma dialogada sobre la obligatoriedad de una ofrenda votiva por una milagrosa lluvia en el siglo XII.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26002','religioso','Santa Apostólica Iglesia Catedral de Santa María de Astorga y Palacio Episcopal','Celebraciones solemnes en honor a Santo Toribio en abril y la gran procesión de la Virgen de la Majestad en agosto. Durante la Cuaresma y Semana Santa (Interés Turístico Nacional) destaca el viacrucis de los pendones y el recogimiento de sus cofradías medievales. Recibe miles de peregrinos de la encrucijada del Camino Francés y la Vía de la Plata.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90217','religioso','Santuario de la Virgen de la Peña','Romería mayor el último domingo de mayo, congregando a miles de fieles del Bierzo que ascienden a pie por veredas escarpadas hasta el santuario colgado en la roca, entonando cantos tradicionales y realizando ofrendas de velas exvoto.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24115','religioso','Basílica de Nuestra Señora de la Encina e Iglesia de Santiago de Peñalba (Valle del Silencio)','Fiestas de la Encina del 5 al 10 de septiembre, con una procesión solemne donde los pueblos de la comarca acuden portando trajes tradicionales bercianos y carros votivos. Paralelamente, el Valle del Silencio registra un flujo místico constante hacia las cuevas eremíticas de San Genadio.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24209','religioso','Iglesia de Santiago Apóstol (Puerta del Perdón) y Colegiata de Santa María','Celebración del Año Santo Jacobeo (cuando el 25 de julio cae en domingo). La Iglesia de Santiago abre solemnemente su "Puerta del Perdón", el único lugar del mundo junto a Santiago de Compostela donde los peregrinos impedidos físicamente por enfermedad pueden obtener las indulgencias plenarias y la remisión de los pecados.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34120','religioso','Santa Iglesia Catedral Basílica de San Antolín (La Bella Desconocida) y su Cripta Visigótica','Festividad de San Antolín el 2 de septiembre. Los files participan en una solemne liturgia capitular y descienden en masa a las profundidades del templo para cumplir el rito etnográfico de beber agua del pozo milagroso de la cripta, al que se atribuyen propiedades curativas y protectoras frente a dolencias físicas.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34047','religioso','Monasterio de San Zoilo, Iglesia de Santiago e Iglesia de Santa María del Camino','Festividad de San Zoilo el 27 de junio con procesiones solemnes que custodian su arqueta de plata medieval. Celebración del Corpus Christi con imponentes alfombras de flores que cubren todo el casco urbano histórico para el paso de la custodia, movilizando a miles de peregrinos de la ruta jacobea.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34074','religioso','Iglesia de San Martín de Tours','Conmemoración litúrgica y procesión del Milagro de la Hostia cada año en las vísperas del Corpus Christi. Goteo ininterrumpido y diario de miles de peregrinos internacionales que visitan el templo románico puro para orar y sellar sus credenciales jacobeas.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34215','religioso','Iglesia de Santa María la Blanca (El Santuario de las Cantigas)','Fiestas patronales de la Virgen en septiembre, precedidas de una solemne bajada nocturna iluminada con antorchas. Romerías de las cruces de las parroquias vecinas de Tierra de Campos que convergen en la monumental estructura fortificada durante la primavera.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90488','religioso','Iglesia-Convento de la Anunciación de Nuestra Señora (Madres Carmelitas Descalzas)','Fiestas Patronales o "Santas" del 14 al 22 de octubre. Destacan las magnas procesiones de la imagen de la santa y la reliquia de su brazo, con la tradicional "limpieza del sepulcro" y la llegada de millares de peregrinos mundiales del circuito "Huellas de Teresa". El 27 de agosto se conmemora solemnemente la Transverberación de su corazón.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37011','religioso','Catedral Nueva de la Asunción de la Virgen, Catedral Vieja de Santa María y Convento de San Esteban (Dominicos)','Fiestas de la Virgen de la Vega el 8 de septiembre, precedidas por una espectacular y multitudinaria ofrenda de flores tradicional con trajes charros. Durante la Semana Santa (Declarada de Interés Turístico Internacional) la ciudad monumental se convierte en un imponente escenario de fe y austeridad castellana.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37061','religioso','Santuario de Nuestra Señora de la Peña de Francia','Festividad de la Virgen el 8 de septiembre. Peregrinaciones multitudinarias a pie y a caballo desde toda la comarca de la Sierra de Francia y las provincias limítrofes. Destaca la subida nocturna con antorchas por sinuosos senderos de montaña y la procesión perimetral por las murallas del risco bajo un hondo recogimiento popular.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37003','religioso','Santa Apostólica Iglesia Catedral de Santa María','Festividad de San Sebastián el 20 de enero con solemnes cultos y procesión de la arqueta barroca por el recinto amurallado medieval. Durante la Semana Santa mirobriguense destaca la sobriedad litúrgica y estética de sus cofradías de origen bajomedieval en un entorno histórico intacto.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37346','religioso','Ermita del Santo Cristo de Cabrera','La tradicional e imponente romería a pie se celebra el 18 de junio. Decenas de miles de fieles caminan descalzos o portando pesadas cruces de madera durante toda la noche desde Salamanca capital (recorriendo más de 30 kilómetros) y los cortijos ganaderos de los alrededores, colapsando las dehesas del entorno del santuario.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40194','religioso','Santa Iglesia Catedral de Nuestra Señora de la Asunción y de San Frutos, Convento de los Carmelitas Descalzos y Santuario de Nuestra Señora de la Fuencisla','Festividad de San Juan de la Cruz el 14 de diciembre con vigilias místicas y procesión claustral de su osamenta. El último domingo de septiembre se celebra la fiesta mayor de la Fuencisla, precedida por el espectacular traslado procesional de la Virgen arropada por la Academia de Artillería desde la Catedral hasta su santuario bajo las peñas. El 25 de octubre destaca la festividad de San Frutos, con el tradicional "Milagro de la Hoja" cantado en el trascoro catedralicio.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40044','religioso','Ermita de San Frutos (Priorato de San Frutos)','Gran romería el 25 de octubre, festividad de San Frutos. Miles de peregrinos de toda la provincia y de tierras castellanas colindantes acceden a pie cruzando los senderos rocosos de los cañones fluviales hasta el promontorio sagrado. Se realiza la bendición tradicional de los campos y el rito de pasar tres veces por debajo del altar del santo para obtener salud ósea.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40063','religioso','Santuario de Nuestra Señora del Henar','Romería de la Virgen del Henar el domingo siguiente a la Natividad de Nuestra Señora (septiembre), considerada una de las más concurridas y antiguas de la Meseta Norte. Los devotos acuden portando trajes regionales para cantar las tradicionales jotas castellanas durante la procesión de la imagen por la pradera que rodea el templo.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40185','religioso','Monasterio de Nuestra Señora de la Soterraña','Fiestas patronales del 6 al 11 de septiembre en honor a la Virgen de la Soterraña. Destaca la tradicional ofrenda de cirios monumentales exvoto y la procesión claustral por las naves y el claustro medieval bajo el canto solemne de preces tradicionales.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42173','religioso','Ermita de San Saturio, Concatedral de San Pedro Apóstol y Monasterio de San Juan de Duero','Festividad de San Saturio el 2 de octubre. Destaca la multitudinaria procesión de las reliquias del santo desde la Concatedral hasta su ermita rupestre. Miles de files cruzan a pie el paseo fluvial del río Duero para acceder a la cueva sagrada y besar el busto-relicario barroco.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42113','religioso','Colegiata de Santa María de la Asunción y Convento de Santa Isabel','Festividad de los Cuerpos Santos el 12 de noviembre con solemnes cultos cantados por las cofradías locales. El primer viernes de marzo se celebra el masivo y devoto besapiés al Santo Cristo de Medinaceli, atrayendo a devotos de toda la meseta soriana y de Guadalajara.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('47186','religioso','Santa Iglesia Catedral de Nuestra Señora de la Asunción, Santuario Nacional de la Gran Promesa, Iglesia Penitencial de Nuestra Señora de la Angustias e Iglesia de San Benito el Real','La Semana Santa de Valladolid (Declarada de Interés Turístico Internacional) es el culmen absoluto de la piedad popular de la Meseta Norte. Destaca el Viernes Santo con el sobregogedor Sermón de las Siete Palabras en la Plaza Mayor y la Procesión General del Santo Entierro, donde desfilan cronológicamente 33 pasos barrocos monumentales. El primer viernes de marzo se celebra el devoto y masivo besapiés al Cristo de Medinaceli en San Martín, y el 14 de mayo la festividad litúrgica del Beato Bernardo de Hoyos en el Santuario Nacional.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('47043','religioso','Monasterio de Santa María de la Santa Espina','Peregrinación continua y devota a lo largo de todo el año, con un repunte masivo de fieles de los valles de los ríos Bajoz y Sequillo durante las celebraciones de la Exaltación de la Santa Cruz (14 de septiembre) y las festividades marianas tradicionales de la dehesa.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('47085','religioso','Colegiata de San Antolín, Convento de San José (Madres Carmelitas) y Monasterio de Santa Clara','Semana Santa de Medina del Campo (Declarada de Interés Turístico Internacional), caracterizada por poseer las procesiones de disciplina documentadas más antiguas de España (originadas por San Vicente Ferrer en 1411). Destacan las procesiones de silencio absoluto y el desfile de imponentes pasos renacentistas y barrocos sin ruedas, portados a hombros con un rigor ascético extremo.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('47101','religioso','Iglesia de los Santos Juanes (La Giralda de Castilla) y Ermita de Nuestra Señora de la Concepción','Celebración de la bajada de la Virgen el 30 de noviembre y la subida de regreso el 8 de diciembre, conocida popularmente como la "Fiesta de la Virgen de los Pegotes" (Declarada de Interés Turístico Nacional). La imagen es trasladada de noche en un carruaje de época arrastrado por mulas, escoltado por miles de files que iluminan el camino con hogueras y antorchas hechas de resina ("pegotes"), mientras se cantan piropos y preces tradicionales.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('49275','religioso','Santa Iglesia Catedral del Salvador, Iglesia de Santa María de la Horta e Iglesia de San Juan de Puerta Nueva','La Semana Santa de Zamora (Declarada de Interés Turístico Internacional) es una de las manifestaciones de fe pública más famosas y puras de la cristiandad. Destacan los desfiles procesionales nocturnos en silencio absoluto, el sobregogedor canto del Miserere por cientos de cofrades en la Plaza de Viriato la noche del Jueves Santo y la procesión del Juramento del Silencio ante el Cristo de las Injurias el Miércoles Santo. El lunes de Pentecostés se celebra la Romería de la Virgen de la Concha (Romería de La Hiniesta), trasladando a la patrona a pie hasta el municipio vecino en un rito de concordia del siglo XIII.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('49065','religioso','Santuario de Nuestra Señora de la Bandera','Festividad de la Virgen el 8 de septiembre. Los fieles acuden al santuario elevado para rendir honores, destacando las procesiones tradicionales por el escarpado casco histórico fortificado y los ancestrales toques de campana manuales que se escuchan a ambos lados de la frontera fluvial del Duero.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('49177','religioso','Santuario de Nuestra Señora de la Carballeda','Gran Romería de la Carballeda celebrada el tercer domingo de septiembre. Decenas de miles de peregrinos de las provincias de Zamora, León y de la región trasmontana portuguesa acuden a pie y a caballo para participar en las misas solemnes, el canto de las loas tradicionales y la procesión perimetral de la Virgen por los campos de robledales.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('49219','religioso','Colegiata de Santa María la Mayor e Iglesia de San Lorenzo el Real','Festividad de la Virgen del Canto el 8 de septiembre con una multitudinaria ofrenda de flores y frutos de las bodegas tradicionales y cooperativas agrarias, portados con trajes tradicionales de toresana. Durante el ciclo de Semana Santa destaca el sobregogedor desfile nocturno del Santo Entierro, donde se bendicen las tierras.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90332','religioso','Iglesia Parroquial de Nuestra Señora de la Asunción, Casa Natal de San Juan de Ávila y Casa Natal de San Juan Bautista de la Concepción','Festividad de San Juan de Ávila el 10 de mayo y de San Juan Bautista de la Concepción el 14 de febrero, con solemnes vigilias de oración, cultos litúrgicos mayores y procesiones de sus reliquias por el casco histórico. Recibe un flujo continuo de peregrinaciones sacerdotales de toda España y seminarios europeos durante todo el año.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('13005','religioso','Santuario de Nuestra Señora de las Cruces y Convento de los Padres Pasionistas (Santuario del Santo Cristo de la Luz)','Dos grandes romerías anuales: la de la Ascensión (primavera) y la del primer domingo de septiembre. Decenas de miles de peregrinos de toda la comarca de La Mancha Occidental se desplazan a pie por las veredas agrarias hasta el santuario rural, portando la imagen sobre carretas votivas engalanadas.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45168','religioso','Santa, Metropolitana y Primada Iglesia Catedral de Santa María; Iglesia de Santo Tomé; Monasterio de San Juan de los Reyes; Convento de San Pedro Mártir','La solemnidad del Corpus Christi (Declarada de Interés Turístico Internacional) es la manifestación máxima de la fe toledana; la colosal custodia procesiona sobre alfombras de tomillo aromático por las calles cubiertas de toldos medievales. El 23 de enero se celebra San Ildefonso con magnos cultos capitulares, y el 15 de agosto la festividad de la Virgen del Sagrario, donde los fieles cumplen el rito tradicional de beber agua de los botijos milagreros en el claustro catedralicio.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45081','religioso','Santuario de Nuestra Señora de la Caridad y Hospital de la Caridad','Fiestas patronales del 31 de agosto al 1 de septiembre. El 31 de agosto por la noche se celebra la multitudinaria procesión de la Virgen de la Caridad por las calles engalanadas de la villa, con gran afluencia de peregrinos a pie de toda la comarca de la Sagra y del sur de la provincia de Madrid.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45165','religioso','Basílica de Nuestra Señora del Prado y Colegiata de Santa María la Mayor','Celebración de las Fiestas de las Mondas el sábado siguiente a la Pascua de Resurrección (Declarada de Interés Turístico Nacional), un ancestral rito de origen romano cristianizado en el siglo VII, donde los pueblos de la comarca de las Antiguas Tierras de Talavera acuden en carros votivos cargados de ofrendas de cera y grano para la Virgen. Su festividad litúrgica se conmemora el 8 de septiembre.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45166','religioso','Ermita de la Veracruz e Iglesia Parroquial de Nuestra Señora de la Asunción','Fiestas en honor a Jesús Nazareno a finales de agosto, destacando las procesiones austeras y solemnes por su singular e imponente Plaza Mayor porticada de estilo manchego tradicional, acompañadas de promesas silenciosas y mandas a pie.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16078','religioso','Santa Iglesia Catedral Basílica de Santa María y San Julián','Festividad de San Julián el 28 de enero. El Cabildo Catedralicio expone públicamente la monumental arqueta de plata que custodia sus restos santos para la veneración de los fieles. Durante la Semana Santa de Cuenca (Declarada de Interés Turístico Internacional) destaca la sobrecogedora procesión "Camino del Calvario" en la madrugada del Viernes Santo, con el atávico rito sonoro de "las turbas" desafiando al paso del Nazareno.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16112','religioso','Monasterio de la Merced (Iglesia de San Esteban) y Ermita de la Virgen de la Alcarria','Fiestas del Santo Cristo de los Milagros en mayo, con solemnes cultos y procesiones por el escarpado entramado urbano fortificado, acompañadas de promesas tradicionales y marchas silenciosas a pie de los agricultores de la comarca.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16190','religioso','Iglesia Parroquial de Santiago Apóstol y Santuario de la Virgen de Rus','Romería de la Virgen de Rus celebrada el Domingo de Resurrección (para traer la imagen al pueblo) y el lunes de Pentecostés (para su regreso al santuario rural), en un rito de hermandad compartido con la vecina localidad de El Provencio. Las cuadrillas de anderos portan el paso a una velocidad extrema en una carrera vertiginosa por los caminos agrarios manchegos que congrega a miles de personas.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19257','religioso','Santuario de Nuestra Señora de la Salud de Barbatona y Santa Iglesia Catedral Basílica de Santa María de Sigüenza','La célebre Romería de Barbatona se celebra el segundo domingo de mayo, congregando a decenas de miles de peregrinos de Guadalajara, Soria y Madrid que caminan a pie y descalzos desde la ciudad mitrada de Sigüenza y los valles del Henares. Su festividad se extiende con la "Octava de Barbatona" en septiembre. En la catedral destaca la procesión de los faroles en honor a la Virgen de la Mayor el domingo posterior a la Asunción.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19212','religioso','Insigne Iglesia Colegiata de la Asunción y Convento del Carmen (Fundación Teresiana)','Fiestas en honor al Santo Cristo de la Agonía en septiembre, con solemnes cultos cantados por las cofradías locales y traslados tradicionales. Goteo constante y regular de peregrinos mundiales que recorren el circuito teresiano del Ducado de Pastrana.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19266','religioso','Iglesia Parroquial de la Asunción de Nuestra Señora','Fiestas patronales de la Virgen de la Salceda del 7 al 10 de septiembre, destacando la solemne procesión de la imagen escoltada por las cofradías tradicionales a lo largo de sus famosas calles con soportales castellanos, acompañada de ofrendas agrícolas de los labriegos de la comarca de la Alcarria.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08127','religioso','Santa María de Montserrat (Abadía de Montserrat y Basílica)','Festividad de la Virgen de Montserrat el 27 de abril. Atrae anualmente a cientos de miles de peregrinos internacionales y nacionales. Destaca la mítica marcha nocturna a pie "A Montserrat a peu" desde Barcelona y las comarcas del Bages y el Baix Llobregat. Diariamente se celebra el canto de la Escolania de Montserrat (el coro de niños cantores más antiguo del continente occidental), interpretando el Virolai y la Salve Regina.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08003','religioso','Catedral de la Santa Cruz y Santa Eulalia, Basílica de la Purísima Concepción y Basílica de Santa María del Mar','Fiestas de Santa Eulalia en torno al 12 de febrero, con solemnes preces litúrgicas capitulares y la bajada tradicional a la cripta. Fiestas de la Merced el 24 de septiembre, con una multitudinaria procesión eclesiástica y ciudadana de la patrona de la archidiócesis. Durante la festividad del Corpus Christi se celebra el rito bajomedieval de "L''ou com balla" (el huevo que baila) en las fuentes de los claustros catedralicios.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08113','religioso','Santuario de la Cova de San Ignacio y Basílica de la Colegiata de Santa María (La Seu)','Festividad de San Ignacio de Loyola el 31 de julio. Peregrinación continua y regular de jesuitas, teólogos y laicos de los cinco continentes que recorren el histórico Camino Ignaciano y acuden de forma monográfica a realizar ejercicios espirituales en silencio contemplativo.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08026','religioso','Catedral de San Pedro de Vic e Iglesia de la Piedad','Festividad de San Bernardo Calbó el 25 de octubre, abriéndose solemnemente su urna relicario barroca de plata en la catedral. Durante la Cuaresma se celebran solemnes vía crucis tradicionales por el casco histórico medieval bajo cantos polifónicos de gran antigüedad.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90593','religioso','Conjunto Monumental de las Iglesias de San Pedro de Terrassa (Seu d''Ègara)','Festividad de San Pedro el 29 de junio, con la celebración de liturgias en rito hispano-visigodo que conmemoran la antigüedad del obispado de Ègara. Goteo constante e ininterrumpido de historiadores, teólogos y peregrinos culturales de Europa Occidental que visitan el complejo para orar en sus ábsides milenarios.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08205','religioso','Monasterio de Sant Cugat','Festividad de San Cugat el 27 de julio, con solemnes traslados y ofrendas de las hermandades tradicionales de la comarca del Vallès. Durante todo el año se registran visitas monográficas a su claustro para la meditación litúrgica guiada.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17043','religioso','Santuario de Nuestra Señora de Núria','Festividad de la Virgen de Núria el 8 de septiembre (fiesta de las marianas pirenaicas) y San Gil el 1 de septiembre. Se celebra un antiquísimo rito de fertilidad etnográfico único: las mujeres que desean tener descendencia introducen la cabeza en la olla de San Gil mientras otra persona hace tocar la campana tantas veces como hijos desean tener, rito documentado y presenciado por miles de files anuales.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17147','religioso','Monasterio de Santa María de Ripoll','Festividad de San Eudaldo el 11 de mayo con solemnes preces litúrgicas y traslados de su arqueta relicario de plata barroca. Goteo ininterrumpido y diario de peregrinos culturales y de fe de Europa Occidental que visitan el cenobio considerado la cuna monástica e hagiográfica del nacimiento del territorio.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18005','religioso','Santa Iglesia Catedral de Santa María de Girona y Basílica de San Félix (Sant Feliu)','Fiestas de San Narciso en torno al 29 de octubre, destacando la multitudinaria e imponente bajada a su cripta en la iglesia de San Félix para venerar su cuerpo incorrupto en una solemne urna de plata barroca, rito asociado al milagro hagiográfico de las moscas sagradas que salvaron la ciudad de los asedios franceses.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25186','religioso','Santuario de Nuestra Señora del Milagro (Santuari del Miracle)','Festividad principal el 3 de agosto, conmemorando la fecha exacta de la aparición mariana. Reúne a miles de peregrinos de la comarca del Solsonès y del centro de Cataluña que acuden a pie y en caravanas procesionales tradicionales, cumpliendo promesas familiares y participando en los cantos de los gozos litúrgicos.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27008','religioso','Catedral de la Seu Vella y Catedral Nueva de Lleida','Fiestas patronales en honor a San Anastasio en torno al 11 de mayo, destacando las procesiones solemnes y las ofrendas tradicionales. Durante la Semana Santa ilerdense posee un hondo calado la Procesión de los Dolores el Domingo de Ramos, caracterizada por un riguroso ascetismo y una masiva participación de las cofradías penitenciales históricas.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25040','religioso','Santuario del Santo Cristo de Balaguer e Iglesia de Santa María','Fiestas del Santo Cristo a principios de noviembre (festividad de San Alodio). Atrae a decenas de miles de fieles de las comarcas de la Noguera, el Urgell y el Segrià, quienes realizan marchas a pie nocturnas y guardan largas colas para acceder al camerín a besar el pie de la sagrada imagen en cumplimiento de promesas de salud.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('43176','religioso','Real Monasterio de Santa María de Poblet','Flujo constante de turismo místico-cultural y retiros espirituales durante todo el año. Destacan las solemnes liturgias cistercienses cantadas en latín por la comunidad monástica durante las grandes solemnidades del año litúrgico (Pascua, Navidad y la Asunción de la Virgen el 15 de agosto), atrayendo a peregrinos de toda Europa.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('43148','religioso','Santa Tecla Catedral Basílica Metropolitana y Primada de Tarragona','Fiestas de Santa Tecla del 14 al 24 de septiembre (Declaradas de Interés Turístico Nacional). El acto cumbre es la multitudinaria y emotiva procesión del Brazo de Santa Tecla por las calles medievales del casco antiguo, escoltada por el "Séquito Popular" y danzas ancestrales, culminando con la espectacular "Entrada de Santa Tecla" en la catedral bajo el repique de campanas y fuegos artificiales.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('43123','religioso','Santuario de Nuestra Señora de la Misericordia e Iglesia Prioral de San Pedro','Fiestas de la Virgen de la Misericordia el 25 de septiembre. Miles de fieles de toda la comarca del Baix Camp acuden a pie en peregrinación hasta el santuario barroco, donde destacan los tradicionales bailes de diablos (Ball de Diables) y las espectaculares ofrendas de fuego en el interior de la plaza del templo como cumplimiento de promesas.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03003','religioso','Monasterio de la Santa Faz (Santuario de la Santa Faz) y Concatedral de San Nicolás de Bari','Peregrinación de la Santa Faz (conocida popularmente como "La Peregrina"), celebrada el segundo jueves posterior a la Semana Santa. Reúne a más de 300.000 peregrinos que caminan a pie vestidos con el tradicional blusón negro y portando cañas con un ramito de romero desde la Concatedral hasta el monasterio rural, constituyendo la segunda romería más multitudinaria de España tras el Rocío.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03016','religioso','Basílica de Santa María de Elche','Representación litúrgica y musical del Misteri d''Elx los días 14 y 15 de agosto (Declarado Obra Maestra del Patrimonio Oral e Inmaterial de la Humanidad por la UNESCO). El 29 de diciembre se celebra la Fiesta de la Venida de la Virgen, conmemorando el hallazgo de la imagen en las playas de El Altet, con una multitudinaria romería al amanecer desde el paraje costero.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03027','religioso','Santa Iglesia Catedral del Salvador y Santa María, Santuario de Nuestra Señora de Monserrate e Iglesia de Santiago Apóstol','Fiestas de la Virgen de Monserrate en septiembre, con solemnes traslados capitulares y bajadas tradicionales desde su santuario de la peña. Su Semana Santa (Declarada de Interés Turístico Internacional) destaca por la fastuosidad y el valor artístico de sus tronos esculpidos por imagineros de la escuela barroca levantina como Francisco Salzillo y por la singular procesión del Santo Entierro de gran rigor litúrgico.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46250','religioso','Santa Iglesia Catedral-Basílica Metropolitana de la Asunción de Nuestra Señora (Capilla del Santo Cáliz), Real Basílica de Nuestra Señora de los Desamparados e Real Colegio Seminario del Corpus Christ','La Fiesta de la Virgen de los Desamparados se celebra el segundo domingo de mayo, registrando el multitudinario y fervoroso rito del "Trasllat" (Traslado), donde la imagen es llevada a hombros entre masas de fieles que pujan por tocar su manto bajo lluvias de pétalos. El Corpus Christi de Valencia es una de las liturgias más antiguas y monumentales de Europa, destacando las procesiones con las Rocas (carros triunfales de madera del siglo XIV). El 22 de enero se conmemora solemnemente a San Vicente Mártir con procesiones capitulares y apertura de relicarios.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12141','religioso','Santuario de la Mare de Déu de la Balma','La festividad y Romería al Santuario de la Virgen de la Balma tienen lugar cada año el 8 de septiembre (precedida por procesiones nocturnas el día 7). El acto central se caracteriza por el sonido del tabalet, la dulzaina y danzas tradicionales. Al llegar a la Cruz Cubierta, se escenifica el ancestral rito del "Dimoni de la Balma" (el diablo) que trata de impedir el avance procesional, entablando una teatral batalla mística contra un ángel en la que el Bien sale victorioso.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12080','religioso','Basílica de Santa María la Mayor (Basílica del Sexenni)','Cada seis años, durante la segunda quincena de agosto, se celebra el célebre e histórico Sexenni de Morella (Declarado de Interés Turístico Nacional y Bien de Interés Cultural Inmaterial). Consiste en un multitudinario novenario de fiestas en honor a la Virgen en agradecimiento por el fin de una plaga de peste bubónica en 1672. Destacan las danzas tradicionales ancestrales de gremios medievales (els Torneros, els Teixidors) que bailan por las calles alfombradas de tapices de papel rizado hechos a mano. Anualmente se realiza una dura romería a pie de 24 kilómetros al Santuario de la Vallivana el primer sábado de mayo.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12104','religioso','Santa Iglesia Catedral Basílica de la Asunción y Ermita de Nuestra Señora de la Esperanza','Romería de la Virgen de la Esperanza en torno al 8 de septiembre, donde los peregrinos ascienden a pie hasta el paraje natural del manantial sagrado. Durante la Semana Santa segorbina destacan los viacrucis solemnes de origen bajomedieval por su casco urbano amurallado clasicista.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10087','religioso','Real Monasterio de Santa María de Guadalupe','La festividad máxima se celebra el 8 de septiembre (Día de Extremadura), precedida por la llegada de las multitudinarias "Marchas a Guadalupe", donde miles de peregrinos a pie y a caballo cruzan la sierra por los doce Caminos Históricos tradicionales. El 12 de octubre destaca la Fiesta de la Hispanidad, con solemnes liturgias de rango pontificio que conmemoran su patronazgo sobre el Nuevo Mundo, atrayendo flujos continuos de delegaciones hispanoamericanas.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10050','religioso','Santuario del Santo Cristo de la Agonía (Puerto del Gamo)','Fiestas grandes del 14 al 16 de septiembre, coincidiendo con la Exaltación de la Santa Cruz. Destaca la sobregogedora procesión nocturna del Cristo por el puerto de montaña, escoltado por las hermandades tradicionales que iluminan los riscos con hachones de resina, en un ambiente de riguroso silencio y promesas de salud descalzas.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10148','religioso','Catedral Vieja de Santa María, Catedral Nueva de Plasencia y Santuario de la Virgen del Puerto','Romería de la Virgen del Puerto el domingo siguiente a la Pascua de Resurrección, congregando a miles de fieles de las comarcas del Jerte, la Vera y el Ambroz que ascienden a pie hasta el monte del santuario. En las catedrales se celebran solemnes cultos el 16 de enero con la apertura del arcón de las reliquias de los santos visigodos.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06026','religioso','Monasterio de Tentudía (Santuario de Nuestra Señora de Tentudía) y Conventual Santiaguista','Gran Romería de Tentudía celebrada el 8 de septiembre. Miles de fieles y hermandades ecuestres procedentes del sur de Extremadura y del norte de Andalucía Oriental ascienden a pie y a caballo hasta la cumbre montañosa para celebrar liturgias capitulares solemnes y procesionar la sagrada efigie por el recinto amurallado medieval.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06018','religioso','Basílica de Santa Eulalia de Mérida (Templo y Xenodochium) e Concatedral de Santa María de la Asunción','Fiestas patronales de Santa Eulalia del 9 al 10 de diciembre. Destaca la multitudinaria procesión de las antorchas en la madrugada del 10 de diciembre, rememorando el martirio de la niña santa bajo los decretos de Diocleciano. El municipio registra un flujo continuo de peregrinos jacobeos procedentes de la Vía de la Plata que acuden monográficamente a orar ante el sepulcro primitivo de la mártir.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06010','religioso','Santuario de Nuestra Señora de los Remedios e Iglesia de Santa María del Castillo','Fiestas mayores y Romería de la Virgen de los Remedios el segundo domingo de Pascua de Resurrección (Domingo de Milagros). Los files participan en una solemne liturgia y procesionan la imagen por el llano de la dehesa, destacando el ancestral rito inmaterial de las subastas de los banzos de plata y las promesas que se cumplen descalzas.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15078','religioso','Santa, Apostólica y Metropolitana Iglesia Catedral de Santiago de Compostela','Celebración del Año Santo Jacobeo (Xacobeo) cada vez que el 25 de julio (festividad del Apóstol) cae en domingo, procediéndose a la apertura solemne de la Puerta Santa. Peregrinación de masas continua y global a través de la red internacional de Caminos de Santiago. En las grandes solemnidades litúrgicas destaca el impresionante vuelo del Botafumeiro (colosal incensario del siglo XIX) surcando el crucero del templo a gran velocidad, un rito purificador medieval.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('01013','religioso','Santuario de Nuestra Señora de la Barca','La Romaría de la Barca se celebra el segundo domingo de septiembre, siendo una de las citas de piedad popular costera más populosas de Galicia. Reúne a miles de romeros que acuden como epílogo final del Camino de Santiago para realizar los ritos tradicionales sobre los megalitos de piedra caliza: pasar por debajo de la Pedra do Cadril para sanar dolencias reumáticas y reñir el rezo tradicional sobre la Pedra de Abalar.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15022','religioso','Santuario de San Andrés de Teixido','Romerías continuas de primavera a otoño, con el día grande el 8 de septiembre y el 30 de noviembre. Los files cumplen el ritual inmaterial de portar amuletos de pan cocido de colores (sanandreses) y arrojar piedras en los túmulos sagrados (amilladoiros).','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28009','religioso','Iglesia de Santa María la Real de O Cebreiro','Celebración de las fiestas de la Virgen y del Santo Milagro el 8 y 9 de septiembre. Goteo ininterrumpido de miles de peregrinos del Camino de Santiago Francés que coronan el primer puerto gallego y acuden a postrarse ante el relicario pontificio donado por los Reyes Católicos en 1486.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27028','religioso','Santa Iglesia Catedral Basílica de Santa María de Lugo','Festividad de la Virgen de los Ojos Grandes el 15 de agosto y solemnes procesiones del Corpus Christi con la custodia por el interior del recinto amurallado romano. Goza de una liturgia continua de adoración eucarística nocturna y diurna de carácter perpetuo.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90512','religioso','Santuario de Nuestra Señora de Los Milagros (Monte Medo)','Novenario y gran romería del 3 al 11 de septiembre. Considerada la manifestación de piedad mariana más masiva del interior de Galicia, reuniendo a más de 100.000 fieles que realizan marchas penitenciales a pie durante toda la noche desde la capital y las comarcas vecinas de la Limia y Celanova.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34004','religioso','Capilla de San Benito de Milmanda','Grandes romerías de "sanación" el 21 de marzo y el 11 de julio. Miles de peregrinos gallegos y del norte de Portugal cumplen el sobregogedor rito de "pasar el pañuelo" por la efigie del santo y posteriormente frotárselo por bultos, verrugas o tumores para buscar la curación milagrosa.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('36011','religioso','Santuario de la Virgen Peregrina e Basílica de Santa María la Mayor','Fiestas de la Peregrina durante la segunda semana de agosto, destacando la multitudinaria ofrenda de flores tradicional y la procesión nocturna de la imagen mariana, escoltada por miles de peregrinos nacionales y extranjeros de la ruta lusa.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28079','religioso','Basílica de Jesús de Medinaceli, Catedral de la Santa María la Real de la Almudena e Iglesia de San Isidro el Real','El primer viernes de marzo se celebra el multitudinario y devoto besapiés a Jesús de Medinaceli, donde cientos de miles de fieles de toda España (incluyendo la Familia Real) guardan días de cola en las calles del centro. El 15 de mayo se celebra la festividad de San Isidro Labrador con la tradicional romería a su Ermita del Santo y la bendición de las aguas de su pozo milagroso. El 9 de noviembre destaca la procesión de la Virgen de la Almudena por la Plaza Mayor.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28131','religioso','Capilla provisional de la Virgen Dolorosa de Prado Nuevo y tumba de Amparo Cuevas','El primer sábado de cada mes del año es el epicentro absoluto del fenómeno. Decenas de autobuses y miles de peregrinos de toda España, Portugal, Francia e Italia colapsan la finca arbolada. Se realiza un multitudinario rezo del Rosario a pie en torno al fresno milagroso y procesiones con cantos marianos.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29001','religioso','Santa e Insigne Catedral-Magistral de los Santos Justo y Pastor','Festividad de los Santos Niños el 6 de agosto, con solemnes traslados capitulares y la apertura de su suntuosa cripta subterránea para la veneración de las arquetas de plata. El 13 de noviembre destaca la festividad de San Diego de Alcalá, abriéndose su urna para contemplar su cuerpo incorrupto.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('30015','religioso','Real BasílicaSantuario de la Santísima y Vera Cruz','Celebración de su Año Jubilar Perpetuo e ininterrumpido concedido por la Santa Sede en 1998, que otorga indulgencia plenaria perpetua a los peregrinos. Fiestas patronales del 1 al 5 de mayo (Declaradas de Interés Turístico Internacional), destacando el ancestral y vertiginoso rito inmaterial de los Caballos del Vino y el Solemne Baño de la Cruz en las aguas medicinales del Bañadero para bendecir los campos.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('30030','religioso','Santa Iglesia Catedral de Santa María y Santuario de Nuestra Señora de la Fuensanta (Algezares)','La célebre e imponente Romería de la Fuensanta se celebra el martes posterior a la Feria de Septiembre. Decenas de miles de devotos descienden y ascienden a pie escoltando el trono de la Virgen desde la Catedral hasta su santuario serrano a lo largo de un sinuoso recorrido, en una de las procesiones de masas más populosas del sureste peninsular. En Cuaresma se realiza la tradicional "Bajada".','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31135','religioso','Castillo de Javier y Basílica de Javier','Celebración de las multitudinarias Javieradas los dos primeros fines de semana de marzo. Decenas de miles de peregrinos de toda Navarra y del norte de España caminan a pie decenas de kilómetros cruzando los valles hasta el castillo fortificado. El 3 de diciembre se conmemora la festividad litúrgica mayor con solemnes preces mundiales.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31261','religioso','Real Monasterio de San Salvador de Leyre','Goteo continuo de turismo místico y de fe a lo largo de todo el año. Los files acuden de forma masiva a las Oficinas Litúrgicas para escuchar el canto gregoriano interpretado en directo por la comunidad de monjes Benedictinos. El 22 de octubre destaca la solemnidad litúrgica de las Santas Mártires con procesiones claustrales.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31235','religioso','SantuarioFortaleza de Santa María de Ujué','La tradicional Romería de Ujué se celebra el domingo siguiente al 25 de abril (San Marcos), considerada una de las manifestaciones de piedad popular más antiguas y sobregogedoras de la península (origen en 1341). Los romeros de los pueblos de la Ribera acuden a pie vestidos con túnicas negras de penitentes, descalzos, portando pesadas cruces de madera y arrastrando cadenas en silencio absoluto.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26138','religioso','Santa Iglesia Catedral del Salvador y Ermita de la Virgen de la Plaza','Fiestas del Santo del 10 al 15 de mayo (Declaradas de Interés Turístico Nacional), destacando la Procesión de las Panaderillas y la de la Rueda. Goteo ininterrumpido y masivo de peregrinos del Camino de Santiago Francés que acuden monográficamente a postrarse ante el sepulcro y contemplar el gallinero catedralicio.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26130','religioso','Monasterio de San Millán de Yuso y Monasterio de San Millán de Suso','Romerías tradicionales del Valle del Cárdenas y festividad de San Millán el 12 de noviembre con solemnes liturgias de la comunidad de monjes Agustinos Recoletos. Goteo diario de miles de peregrinos de la cultura y la fe que visitan el complejo declarado Patrimonio de la Humanidad por la UNESCO.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90270','religioso','Abadía de Nuestra Señora de Valvanera','La tradicional Marcha a Valvanera (Valvanerada) se celebra en la primavera, reuniendo a miles de caminantes que recorren a pie más de 60 kilómetros desde Logroño hasta el santuario enclavado en la Sierra de la Demanda. Su solemnidad litúrgica se celebra el 8 de septiembre.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21004','religioso','Santuario de San Ignacio de Loyola (Basílica y Santa Casa)','Festividad de San Ignacio de Loyola el 31 de julio, considerada la fiesta mayor de Guipúzcoa. Reúne a miles de peregrinos de los cinco continentes que acuden como inicio oficial del Camino Ignaciano, celebrándose magnas liturgias solemnes de rango pontificio y procesiones claustrales. Goteo ininterrumpido anual de teólogos, jesuitas y laicos que realizan tandas monográficas de Ejercicios Espirituales.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21014','religioso','Santuario de Nuestra Señora de Arantzazu','Festividad de la Virgen de Arantzazu el 9 de septiembre. Reúne a decenas de miles de files y caminantes de todo el País Vasco y del norte navarro que ascienden a pie cruzando las escarpadas sendas montañosas del macizo de Aizkorri. Tradicionales romerías de las parroquias y cooperativas agrarias locales durante todo el ciclo de primavera a otoño.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('48020','religioso','Basílica de Nuestra Señora de Begoña e Catedral de Santiago de Bilbao','La gran festividad de la Amatxu se celebra el 11 de octubre, destacando la multitudinaria e imponente peregrinación nocturna al amanecer, donde decenas de miles de vizcaínos de todas las cuencas mineras y costeras caminan a pie hasta la colina de la basílica. El 15 de agosto se celebra la Asunción con magnas ofrendas tradicionales de los marineros y barcos del Nervión.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50039','religioso','Santuario de Nuestra Señora de Estíbaliz (Argandoña) e Santa Iglesia Catedral de María Inmaculada (Catedral Nueva)','Fiesta de la Virgen de Estíbaliz el 1 de mayo, con una multitudinaria romería comarcal caracterizada por el sonido de los txistus, deportes rurales tradicionales vascos y el concurso gastronómico tradicional. El 28 de abril destaca la festividad de San Prudencio, ascendiendo las gentes a las campas del cerro de Armentia para las preces agrarias solemnes.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23064','religioso','Sepulcro de Ángel Custodio Pérez Martínez en el Cementerio Municipal de Noalejo y Casa-Santuario de La Hoya (Hoya del Salobral)','Peregrinación masiva el último domingo de abril y durante el aniversario de su muerte (15 de mayo). Miles de files de Jaén, Granada, Córdoba y Cataluña colapsan la aldea de La Hoya para tocar las paredes de su casa, rezar en su habitación y ungirse con el aceite bendecido de sus lámparas exvoto, antes de desplazarse a Noalejo a besar su lápida.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23099','religioso','Ruta de los Santones de la Sierra y Parajes de Sanación de Luis "Luisico" y Manuel','Goteo diario de fieles y romerías estacionales espontáneas en los cortijos serranos donde ejercieron su ministerio místico. Los devotos acuden buscando remedios para dolencias crónicas y protección del campo mediante la oración e intercambio de reliquias personales.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23033','religioso','Ruta de los Santones de Frailes y Ermitas de San Antonio','Goteo constante de fieles a lo largo del año. Celebración estacional de cultos y reuniones populares en torno a las fechas de su nacimiento y fallecimiento, donde los devotos se intercambian reliquias textiles y rezos tradicionales de protección.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('38039','religioso','Capilla y Cripta de San Luis el Siervo (El Santito de Tenerife)','Goteo continuo de files cada martes del año y de forma multitudinaria durante el mes de mayo. Los peregrinos tinerfeños acuden a orar ante sus recuerdos personales y a recoger flores exvoto bendecidas de su altar.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90872','religioso','Ermita del Santo Milagro de los Corporales','Conmemoración litúrgica mayor el 24 de febrero. Se realiza una multitudinaria romería desde el centro urbano hasta el Monasterio del Corpus Christi, recreando las preces medievales de los capitanes cristianos.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90692','religioso','Santuario y Pozo de la Virgen de Umbe (Monte Umbe)','El último sábado de mayo (aniversario de la primera aparición) y cada primer sábado de mes. Miles de peregrinos de todo el País Vasco, Cantabria y el sur de Francia ascienden a la montaña para cumplir el rito etnográfico obligatorio de recoger agua del pozo, frotársela por las dolencias físicas y encender cirios monumentales exvoto.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06037','religioso','Santuario de Nuestra Señora de los Dolores de Chandavila','La festividad principal se celebra el 27 de mayo, reuniendo a miles de files extremeños y de la región del Alentejo portugués. Los devotos realizan marchas a pie descalzos por el bosque de castaños, procesionando la efigie mariana y arrodillándose ante el árbol del milagro, con un hondo recogimiento popular libre de masificación comercial.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90941','religioso','Campas y Huerto de las Apariciones de Ezquioga (Caserío Burgui)','Romerías estacionales silenciosas de grupos tradicionales de fe y goteo constante de investigadores de la historia de la Iglesia y antropólogos en los meses de verano. Los files oran en silencio ante las cruces pétreas efímeras levantadas en la pradera.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05182','religioso','Casa Natal y Altar Popular de Arturo "El Santero de Pedro Bernardo"','Visitas individuales recurrentes y pequeñas romerías comarcales espontáneas de las gentes del Valle del Tiétar durante todo el ciclo de primavera y otoño, portando fotografías y reliquias para ser puestas en contacto con sus enseres personales.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90409','religioso','Ermita de la Virgen de la Fe y los Milagros y Casa del "Santo de Alhabia"','Peregrinación constante durante el mes de mayo y romería tradicional el 14 de septiembre (Día de la Cruz). Los fieles acuden desde la comarca de la Alpujarra Almeriense y el Valle del Andarax a rezar el Rosario en la humilde vivienda del místico y a recoger agua bendecida.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24008','religioso','Iglesia de la Inmaculada Concepción y Sepulcro del "Santo de Arquillos"','Fiestas patronales en honor a San Antón (enero) y solemnes cultos el 14 de diciembre, fecha en la que los agricultores del Condado realizan marchas a pie y promesas de silencio al templo, depositando espigas de trigo exvoto en el presbiterio.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23074','religioso','Iglesia Parroquial de Nuestra Señora de la Asunción y la Fuente del Santo Cristo de las Aguas','El 12 de septiembre se celebra la célebre e histórica Romería del Cristo de la Charca. Miles de personas de las comarcas de La Loma y el Condado acuden descalzas a ungirse con el agua que brota del manantial subterráneo del altar y a bañar prendas de enfermos crónicos.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18117','religioso','Casa-Santuario del Beato Manuel Medina Olmos e Iglesia de la Anunciación','Romería mayor el 30 de agosto, coincidiendo con el aniversario de su martirio. Miles de peregrinos del Marquesado de Zenete y de la cuenca accitana realizan duras marchas a pie subiendo las laderas montañosas para venerar sus reliquias mayores y besar su casa natal.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17005','religioso','Iglesia del Hospital de San Juan de Dios y Cripta del "Santiño de Bujalance"','Festividad litúrgica y traslados tradicionales el 14 de febrero. Los files de la Campiña Alta cordobesa participan en solemnes preces capitulares y descienden a la cripta para cumplir el rito de untarse las frentes con aceites bendecidos exvoto.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29059','religioso','Ermita del Santísimo Cristo de la Misericordia y el Árbol del Milagro','Romería mayor el primer domingo de mayo. Decenas de miles de devotos realizan duras marchas a pie descalzos por la vereda agraria, procesionando la efigie mariana y arrodillándose ante la cruz del humilladero donde se levanta el altar de promesas.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21063','religioso','Iglesia de San Bartolomé Apóstol y Altar Popular del "Santo Santero del Andévalo"','Fiestas patronales del 22 al 24 de agosto. Destaca el ancestral e impactante rito inmaterial de la "Danza de las Espadas" ejecutada por varones delante de la imagen del santo, acompañada de la entrega de exvotos metálicos protectores de la salud infantil.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90402','religioso','Ermita de la Santísima Cruz de Abanilla e Iglesia de San José','Grandes fiestas patronales del 1 al 3 de mayo (Declaradas de Interés Turístico Regional). El 3 de mayo se realiza la multitudinaria romería que traslada la reliquia desde Abanilla hasta Mahoya, donde miles de fieles de la huerta murciana y del sur de Alicante participan en el ancestral y devoto rito del "Baño de la Cruz" en las aguas del río Chícamo para bendecir las tierras agrícolas.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('30037','religioso','Ermita y Altar del "Santo de Torre-Pacheco" (Casa de la fe)','Goteo ininterrumpido e informal de agricultores y peregrinos del Campo de Cartagena cada fin de semana. Los fieles acuden portando flores, botellas de aceite y fotografías de enfermos para ser puestas en contacto directo con su busto conmemorativo rústico.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06036','religioso','Ermita de Nuestra Señora del Buensuceso e Iglesia Parroquial de Santa María Magdalena','Romería de la Virgen del Buensuceso el primer domingo de septiembre, congregando a miles de fieles de la comarca de La Serena que acuden a pie y en caballerías engalanadas a la grupa, destacando las procesiones tradicionales por la pradera bajo el canto solemne de loas tradicionales y las promesas que se cumplen descalzas.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06028','religioso','Santuario de Nuestra Señora de Piedraescrita','La célebre Romería de Piedraescrita se celebra el Lunes de Pascua de Resurrección (Declarada de Interés Turístico de Extremadura). Miles de personas de toda la comarca acuden en espectaculares carrozas engalanadas con flores de papel rizadas a mano y desfiles ecuestres tradicionales de gran vistosidad formal.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('36046','religioso','Ermita de Santa Baia de Ribadumia y la Fuente Sacra de las Verrugas','Romería tradicional de sanación en torno al 10 de diciembre y durante los meses de verano. Miles de peregrinos de la comarca de O Salnés cumplen el sobregogedor rito inmaterial de sumergir pañuelos en el manantial sagrado del altar, frotárselo por bultos o verrugas y dejarlos colgados en las ramas de los arbustos que rodean el templo hasta que se pudran para buscar la curación milagrosa.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('36031','religioso','Ermita de la Virgen de la Peña y Parajes de Sanación de las Místicas Gallegas','Goteo continuo de files y romerías estacionales espontáneas en los cortijos serranos del Condado donde se custodian las reliquias de las santas curanderas locales, buscando remedios para dolencias óseas crónicas y reumas mediante el rezo del Rosario en gallego.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90511','religioso','Iglesia de Santa Comba de Bande (Santuario del fuego sagrado)','Festividad de Santa Comba el 1 de mayo, con solemnes liturgias en rito hispano-visigodo y procesiones austeras con reliquias menores por la dehesa, atrayendo anualmente a teólogos, historiadores y peregrinos de la fe de toda la cornisa cantábrica y del norte de Portugal que acuden a orar en sus ábsides milenarios.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34002','religioso','Santuario de San Benito de Allariz e Iglesia de Santiago','Grandes romerías de "sanación" el 21 de marzo y el 11 de julio. Miles de fieles de toda la provincia de Ourense y del norte luso acuden a pie y guardan largas colas para cumplir el devoto rito de frotar pañuelos por el altar y depositar exvotos de cera con formas antropomorfas completas (cabezas, brazos) tras salvar la vida de enfermedades de tumores.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15023','religioso','Santuario de Nuestra Señora de la Xunqueira','Fiestas grandes de la Virgen de la Xunqueira el 16 de agosto, destacando la multitudinaria procesión por el puerto marítimo costero, donde la imagen es vitoreada y acompañada por las hermandades de marineros tradicionales bajo el disparo masivo de fuegos artificiales en alta mar en cumplimiento de promesas.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90184','religioso','Hornacina y Capilla Popular del "Santo Santero de la Mahía" (Cortijo de la fe)','Goteo continuo e informal de peregrinos de la comarca de Santiago cada fin de semana. Los fieles acuden portando fotografías, exvotos de cera y botellas de aceite de avancarga para ser bendecidas en su altar popular levantado por la propia comunidad vecinal.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28013','religioso','Santuario de Nuestra Señora de Valdeflores','Romería de la Virgen de Valdeflores el 15 de agosto, congregando a miles de fieles del litoral lucense que acuden a pie y guardan largas colas para acceder al camerín elevado a besar el pie de la sagrada imagen en cumplimiento de promesas de salud familiar.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27022','religioso','Ermita de San Juan de Lagostelle y Fuente de Aguas Taumatúrgicas','Festividad de San Juan el 24 de junio, destacando la multitudinaria romería comarcal caracterizada por el rezo de preces tradicionales y el cumplimiento del rito de bañarse los pies en el manantial de aguas medicinales sulfurosas exvoto para obtener la bendición agraria y la salud física.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37007','religioso','Ermita de Nuestra Señora de la Torre e Iglesia Parroquial de San Pedro','Fiestas de la Virgen de la Torre a mediados de agosto, destacando la multitudinaria e imponente bajada de la efigie mariana desde su ermita serrana fortificada por el casco histórico bajo el volteo manual de las campanas tradicionales mudéjares, acompañada de ofrendas tradicionales de los labriegos de la comarca.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37006','religioso','Ermita de la Virgen de la Vega de Doñinos e Iglesia de San Martín','Romería de la Virgen de la Vega el segundo domingo de mayo. Las cuadrillas de labriegos de la comarca del campo charro acuden a pie portando pesadas velas exvoto y carros tradicionales en cumplimiento de promesas familiares de salud agrícola y bendición de las dehesas.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23034','religioso','Santuario de Nuestra Señora de la Fuensanta y la Fuente de la Teja','Romería de la Fuensanta el 15 de agosto. Miles de personas de la comarca de la Sierra Sur y la Campiña de Jaén acuden descalzas a ungirse con el agua que brota del manantial subterráneo del altar y a bañar prendas de enfermos crónicos.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23087','religioso','Ermita de la Virgen de Consolación y Parroquia de San Pedro Apóstol','Fiestas patronales en honor a la Virgen de Consolación del 4 al 11 de septiembre, destacando la multitudinaria e imponente bajada de la efigie mariana desde su ermita serrana por el casco histórico bajo el volteo manual de las campanas tradicionales mudéjares, acompañada de ofrendas tradicionales de los labriegos de la comarca.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18180','religioso','Ermita de la Virgen de las Nieves (Santuario de Alta Montaña)','Romería de la Virgen de las Nieves el 5 de agosto. Se considera la romería más alta de España, donde miles de fieles de la Alpujarra Granadina ascienden a pie y a caballo a más de 3.000 metros de altitud hasta los llanos del Mulhacén para celebrar liturgias capitulares solemnes y procesionar la sagrada efigie por la nieve.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18136','religioso','Santuario de la Virgen de la Cabeza de Montejícar','Fiestas patronales del 6 al 11 de septiembre en honor a la Virgen de la Cabeza. Destaca la tradicional ofrenda de cirios monumentales exvoto y la procesión claustral por las naves y el claustro medieval bajo el canto solemne de preces tradicionales.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33034','religioso','Ermita de la Virgen de la Regalina','Fiesta de la Regalina el último domingo de agosto (Declarada de Interés Turístico). Destaca la multitudinaria procesión que traslada la imagen sobre carros de bueyes engalanados tradicionales hasta el campo que domina el mar, donde se celebran bailes tradicionales de vaqueiros y ofrendas de panes bendecidos.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33068','religioso','Santuario de Nuestra Señora de Garaño','Fiestas patronales en honor a la Virgen de Garaño en septiembre, con solemnes traslados y ofrendas de las hermandades tradicionales de la comarca, destacando las procesiones tradicionales por la pradera bajo el canto solemne de loas tradicionales.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('35019','religioso','Santuario de Santiago de los Caballeros de Gáldar (Eje Jubilar Metropolitano)','Celebración del Año Santo Jacobeo Galdense cada vez que el 25 de julio cae en domingo, procediéndose a la apertura solemne de la Puerta Santa. Peregrinación de masas continua y global a través de la red de Caminos de Santiago de Gran Canaria que cruzan la isla de sur a norte.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('35026','religioso','Basílica de San Juan Bautista de Telde y el Santo Cristo de Telde','Fiestas del Santo Cristo durante el mes de septiembre, destacando la procesión de las antorchas y los fuegos artificiales la noche del 14 de septiembre. Tradicionales romerías de las cuadrillas de labriegos que acuden portando productos agrícolas de la vega del norte en acción de gracias por la salvación de cosechas.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50092','religioso','Ermita de Nuestra Señora de la Consolación de Chiprana','Romería de la Virgen de la Consolación el primer domingo de mayo. Miles de fieles de toda la comarca acuden a pie y guardan largas colas para acceder al camerín elevado a besar el pie de la sagrada imagen en cumplimiento de promesas de salud.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50102','religioso','Iglesia de San Juan Bautista de Fabara e Mausoleo Romano Sacralizado','Festividad de los Santos Mártires en mayo con solemnes liturgias de las cofradías ganaderas locales y traslados tradicionales, destacando la apertura del arcón de las reliquias en el presbiterio y las promesas silenciosas que se cumplen a pie.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23084','religioso','Iglesia Parroquial de Santa Águeda y Ermita de Santa Quiteria','Festividad de Santa Águeda el 5 de febrero y romería tradicional de Santa Quiteria el 22 de mayo. Se conmemora con solemnes traslados desde la ermita rural y ritos etnográficos de reparto de los tradicionales "panecillos de la santa", bendecidos e invocados como exvoto protector de la salud de las familias agrícolas.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23048','religioso','Iglesia de la Asunción de Nuestra Señora y Santuario de la Virgen de la Fuensanta','Fiestas patronales del 2 al 9 de septiembre. El 5 de septiembre se realiza la solemne y multitudinaria procesión del Cristo de la Veracruz por el intrincado trazado medieval de la villa, acompañado de centenares de "promesas" con cadenas y cruces de madera que caminan en estricto silencio nocturno.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18061','religioso','Iglesia Parroquial de Nuestra Señora del Rosario y Ermita del Cristo de la Luz','Fiestas mayores el último fin de semana de agosto, destacando la multitudinaria bajada nocturna iluminada con antorchas. Los fieles realizan marchas a pie desde los cortijos de la Vega de Granada y guardan largas colas para acceder a la hornacina exvoto del altar mayor a presentar prendas de enfermos.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18100','religioso','Iglesia de Santa Isabel e Ermita del Santo Niño de la Vega','Romería del Santo Niño el segundo domingo de septiembre. Las carretas y files acuden en masa al paraje del río Genil, recreando los cantos tradicionales de alabanza y las subastas de los banzos exvoto para portar la imagen en su regreso al centro urbano.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39098','religioso','Santuario de Nuestra Señora de Valvanuz','Gran romería el 15 de agosto. Reúne a decenas de miles de romeros pasiegos que acuden portando trajes tradicionales y bastones, destacando el tradicional salto pasiego y las ofrendas de quesadas y productos de la dehesa a la Virgen bajo la sombra del encinar sagrado.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39068','religioso','Ermita de la Virgen de los Remedios y Procesión de los Picayos','Celebración el 2 de julio. Destaca el ancestral e impactante rito inmaterial de la "Danza de los Picayos", ejecutada por jóvenes cofrades varones y mujeres tocando castañuelas y cantando romances sacros antiguos delante del paso de la Virgen en su subida al cerro.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('36012','religioso','Ermita de la Virgen de las Angustias e Iglesia de Santiago de Redondela','Fiestas mayores en la primera quincena de septiembre, destacando la multitudinaria procesión marítimo-terrestre donde las alfombras florales cubren el casco histórico y la imagen es vitoreada por las hermandades de pescadores tradicionales de la costa.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('36054','religioso','Santuario de San Campio de Lonxe (San Alodio)','Grandes romerías de "sanación" y promesas el 12 y 13 de julio y el segundo domingo de septiembre. Miles de peregrinos de toda Galicia y del norte de Portugal caminan a pie cruzando el río Miño (de ahí su advocación "de Lonxe", de lejos).','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('32043','religioso','Santuario de Nuestra Señora de los Milagros de Maceda e Iglesia de San Pedro','Novenario y gran romería del 3 al 11 de septiembre. Reúne a miles de files que realizan marchas penitenciales a pie durante toda la noche desde los cortijos del valle, cumpliendo promesas familiares y portando exvotos de cera con formas antropomorfas completas.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90001','religioso','Ermita de Nuestra Señora de la Merced de Chanteiro','Fiestas grandes de la Virgen en septiembre, destacando la tradicional "Procesión del Voto", rito municipal eclesiástico del siglo XV donde los vecinos de Ferrol y Ares acuden a pie hasta la ermita costera.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('01004','religioso','Hornacina rústica del "Santo Santero del Barbanza" (Cortijo de la fe)','Goteo continuo de files y peregrinos de la comarca del Barbanza cada fin de semana. Los fieles acuden portando prendas textiles de enfermos crónicos, velas de avancarga y ofrendas agrícolas para ser frotadas por el altar popular de piedra exento.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27016','religioso','Ermita de la Virgen del Faro de Chantada','Gran romería el 8 de septiembre. Miles de fieles de toda la comarca de Chantada y del interior de Lugo realizan marchas a pie subiendo por las escarpadas laderas montañosas hasta el santuario del cerro elevado, portando pesadas velas exvoto y cruces.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27059','religioso','Iglesia Monacal de San Vicente de Pinol e Santuario de la Virgen de Cadeiras','Fiestas patronales de la Virgen de Cadeiras en septiembre, destacando la procesión de gloria y solemnes cultos tradicionales por las laderas del Sil. Goteo ininterrumpido de peregrinos y buscadores espirituales de Europa Occidental que visitan el monumental complejo románico para orar ante sus relieves capitulares y ábsides medievales calados.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37013','religioso','Ermita de Nuestra Señora del Socorro e Iglesia Parroquial de San Nicolás','Fiestas patronales de la Virgen del Socorro del 14 al 18 de agosto, destacando la tradicional bajada de la imagen desde su ermita serrana hasta la parroquia para la celebración de su novena, congregando a miles de fieles de la comarca.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37046','religioso','Santuario de Nuestra Señora del Castañar e Iglesia de Santiago','Romería de la Virgen del Castañar el 8 de septiembre. Miles de fieles de toda la sierra de Béjar y del norte de Cáceres acuden a pie subiendo por las empinadas laderas boscosas hasta el santuario, portando pesadas velas exvoto y carros tradicionales.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23081','religioso','Iglesia Parroquial de Nuestra Señora del Collado y Ermita de San Vicente','Fiestas patronales del 4 al 8 de octubre. Destaca la bajada y posterior procesión de la Virgen del Collado por el escarpado entramado urbano medieval fortificado, acompañada de antiquísimas subastas de banzos y mandas a pie de los serranos de toda la comarca de alta montaña.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23082','religioso','Iglesia de Nuestra Señora de la Asunción y Ermita de San Roque','Fiestas patronales del 13 al 16 de agosto en honor a San Roque. El día 16 de agosto destaca la multitudinaria procesión del santo protector por las calles engalanadas, donde los labriegos locales realizan masivas ofrendas de albahaca fresca para ser bendecida en un rito aromático de gran pureza formal.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18146','religioso','Iglesia Parroquial de Santa María de la Anunciación y Ermita de San Antón','Celebrada el fin de semana más cercano al 16 y 17 de enero. Consiste en una de las manifestaciones pirofestivas y etnográficas más singulares del Altiplano Granadino, donde se encienden monumentales hogueras ("luminarias") en los barrios y los cofrades danzan con los santos en un rito de purificación colectiva agraria.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18056','religioso','Hornacina rústica del "Santo Ermitaño del Altiplano" (Altar de las promesas)','Romerías espontáneas de agricultores y transportistas cada fin de semana. Los fieles realizan marchas a pie por los márgenes de la autovía y los campos de secano, cumpliendo el rito tradicional de depositar herraduras y exvotos metálicos de extremidades en busca de sanación ósea y protección en las rutas.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90029','religioso','Iglesia de Santa María de Bareyo','Romerías estacionales tradicionales de las gentes de la comarca de Trasmiera y visitas litúrgico-culturales organizadas al templo románico puro para orar y contemplar su pila bautismal milenaria durante las festividades marianas.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39047','religioso','Ermita de San Juan de Ris e Iglesia Parroquial de San Pedro','La noche del 23 al 24 de junio se celebra la multitudinaria romería a la ermita costera de Ris. Los fieles participan en preces tradicionales e iluminan la playa con hogueras, cumpliendo el ritual etnográfico obligatorio de lavarse los ojos con el agua del mar bendecida para buscar la protección de la salud física.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('36024','religioso','Santuario de Nuestra Señora de O Corpiño','La gran romería se celebra el 23 y 24 de junio, considerada la manifestación de piedad popular santera y exorcista más impresionante del norte de España. Riadas de miles de fieles de toda Galicia y Asturias colapsan el santuario montañoso; se realizan procesiones donde los afectados gritan preces de liberación y pasan pañuelos e imágenes por el ropaje de la Virgen en busca de sanación mental y espiritual.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('36052','religioso','Monasterio de San Lorenzo de Carboeiro','Romerías tradicionales y goteo constante de fieles que acuden al cenobio románico restaurado para realizar el rito etnográfico obligatorio de frotar pañuelos por las piedras del presbiterio y depositarlos exvoto para obtener la curación de males de la piel y verrugas.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34013','religioso','Iglesia de Santa Mariña de Augas Santas','Festividad de Santa Mariña el 18 de julio. Miles de fieles de toda la comarca de A Limia acuden a pie y guardan largas colas para descender a la "cripta de los hornos", cumpliendo el sobregogedor rito de tocar la piedra del martirio y lavarse con el agua del manantial sagrado subterráneo en cumplimiento de promesas de salud.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('32069','religioso','Santuario de Nuestra Señora del Portal e Iglesia de Santiago','Fiestas grandes de la Virgen del Portal del 7 al 10 de septiembre, destacando la solemne procesión de la patrona por las naves y el casco antiguo medieval, con la tradicional ofrenda de mosto y vino de las bodegas tradicionales en acción de gracias por la protección de las viñas.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('01011','religioso','Iglesia de Santa María de las Arenas y Santuario del Santo Cristo de Fisterra','La festividad principal se celebra el Domingo de Resurrección con la representación de la "Danza de la Danza" de origen bajomedieval. Goteo ininterrumpido y diario de miles de peregrinos internacionales del Camino de Santiago que coronan el Cabo de Finisterre (el epílogo geográfico final) y acuden a postrarse ante la efigie crística.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15055','religioso','Iglesia de Santa María de Neda y el Santo Cristo de la Cadena','Fiestas del Cristo en septiembre, destacando los viacrucis solemnes de origen bajomedieval por su casco urbano, donde los files de la ría de Ferrol acuden a pie portando promesas silenciosas y velas exvoto en cumplimiento de mandas de salud.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27041','religioso','Monasterio de San Salvador de Ferreira de Pantón','Flujo constante de turismo místico-cultural y retiros espirituales durante todo el año. Destacan las solemnes liturgias cistercienses cantadas en gallego por la comunidad de monjas de clausura (el único monasterio femenino de la Ribeira Sacra que mantiene vida monástica ininterrumpida desde el siglo XII) durante las festividades de la Navidad y la Asunción.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90548','religioso','Iglesia Monacal de Santo Estevo de Lousada','Fiestas patronales de Santo Estevo en enero y solemnes cultos tradicionales en honor a la Virgen en septiembre. Goteo ininterrumpido de peregrinos y buscadores espirituales de Europa Occidental que visitan el monumental complejo románico para orar ante sus relieves capitulares y ábsides medievales calados.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37008','religioso','Iglesia Parroquial de San Ginés de Arlés e Ermita de la Virgen de la Cuesta','Fiestas patronales de la Virgen de la Cuesta del 8 al 10 de septiembre, destacando la multitudinaria procesión por su casco histórico fortificado medieval (declarado conjunto histórico), donde los cofrades tradicionales lucen vestimentas charras medievales y se realiza la danza tradicional de los paleos delante del paso.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37005','religioso','Iglesia de Nuestra Señora de la Asunción y la Festividad del Diagosto','Festividad del Diagosto el 15 y 16 de agosto (Declarada de Interés Turístico Nacional). Destaca por el Ofertorio, un ancestral rito de piedad e identidad charra donde los vecinos, ataviados con los suntuosos y pesados trajes tradicionales "de vistas" de origen bajomedieval, se arrodillan de forma física y secuencial ante el altar de la plaza mayor para realizar ofrendas económicas y agrícolas. El 13 de junio se suelta el "Marrano de San Antón", animal bendecido que recorre el pueblo alimentado por los vecinos hasta enero.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06001','religioso','Santuario de Nuestra Señora de Carrión e Iglesia de Santa María del Mercado','Romería de la Virgen de Carrión el domingo de Resurrección y el lunes de Pascua. Riadas de fieles de la comarca de Lácara-Los Baldíos y de las zonas transfronterizas de Portugal acuden al santuario rural para celebrar solemnes preces tradicionales, subastas de los brazos del paso y comidas comunales de hermandad en los encinares.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('13047','religioso','Iglesia de la Inmaculada Concepción y Santuario de Nuestra Señora de las Mercedes','Fiestas mayores en torno al 24 de septiembre, destacando la multitudinaria procesión de gloria de la Virgen por el casco manchego. Durante el ciclo de carnaval se celebra un ancestral rito sincrético folclóricoreligioso en honor a las Ánimas Benditas, con el desfile de las cofradías tradicionales y ofrendas.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45125','religioso','Iglesia de Nuestra Señora de la Asunción, Colegio de los Jesuitas y Convento de la Misericordia','Fiestas patronales del Cristo de la Paciencia en septiembre, destacando los viacrucis solemnes de origen bajomedieval por su casco urbano amurallado, donde las hermandades de las Tierras de Oropesa acuden a pie portando promesas silenciosas y velas exvoto.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03022','religioso','Santuario de Nuestra Señora de los Ángeles e Iglesia Fortaleza de San Bartolomé','Festividad de la Virgen el 2 de agosto, destacando la tradicional romería nocturna iluminada con antorchas que asciende al cabo de San Antonio, donde las hermandades de pescadores tradicionales realizan ofrendas y cantos populares en cumplimiento de promesas marinas.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12022','religioso','Ermita de Nuestra Señora de Loreto e Iglesia Parroquial de Nuestra Señora de los Ángeles','Fiestas patronales de la Virgen en septiembre, destacando la tradicional bajada de la imagen desde su ermita por el escarpado casco urbano fortificado bajo el repique manual de las campanas tradicionales, acompañada de ofrendas de las cooperativas agrícolas de la comarca del Alto Palancia.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90144','religioso','Iglesia Parroquial de la Natividad de Nuestra Señora y Ermita de San Roque','Fiestas patronales del 13 al 17 de agosto en honor a San Roque. El día 16 de agosto destaca la procesión del santo protector por las calles engalanadas, donde los labriegos locales y los files de la comarca de la Comunidad de Calatayud realizan marchas a pie y ofrendas en cumplimiento de promesas familiares de salud.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22160','religioso','Santuario de Nuestra Señora de los Dolores de Naval e Iglesia de Santa María Mayor','Romería de la Virgen de los Dolores el primer domingo de mayo. Miles de fieles de toda la comarca del Somontano acuden a pie subiendo por las empinadas laderas hasta el santuario del cerro elevado, portando pesadas velas exvoto y participando en los cantos tradicionales de las albadas.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44059','religioso','Iglesia Parroquial de la Asunción de Nuestra Señora e Ermita de la Virgen del Loreto','Fiestas patronales a mediados de agosto, destacando la multitudinaria procesión por su casco histórico fortificado medieval (declarado conjunto histórico), donde las cofradías tradicionales lucen ropajes solemnes y se realizan traslados tradicionales por las murallas en estricto silencio nocturno.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33069','religioso','Ermita de la Virgen del Buen Suceso e Iglesia de San Pedro de la Arena','Fiestas de la Virgen en septiembre, destacando la procesión marítimo-terrestre donde la imagen es vitoreada y acompañada por las hermandades de pescadores tradicionales del Nalón, cumpliendo el rito etnográfico obligatorio de frotar pañuelos por el altar y encender velas de avancarga exvoto en cumplimiento de promesas.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39024','religioso','Ermita de la Virgen de la Garita e Iglesia Parroquial de San Cristóbal','Romería de la Virgen de la Garita el 15 de agosto. Destaca la procesión tradicional que traslada la imagen por el casco histórico monumental, escoltada por las hermandades de pescadores tradicionales que cantan los romances sacros medievales de los picayos bajo el sonido de las castañuelas.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90534','religioso','Santuario de Nuestra Señora de la Salud de Saiar','La gran romería se celebra el tercer domingo de septiembre, considerada una de las manifestaciones de piedad popular santera más impresionantes del sur de Galicia. Riadas de miles de fieles de toda la provincia colapsan el santuario montañoso; se realizan procesiones donde los afectados pasan pañuelos e imágenes por el altar de la Virgen en busca de sanación mental y espiritual.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('32052','religioso','Ermita y Parajes Eremíticos de San Pedro de Rocas (Eje Histórico)','Romería tradicional el 29 de junio, con la celebración de liturgias que conmemoran la antigüedad del eremitorio benedictino en pleno corazón de la Ribeira Sacra. Goteo constante e ininterrumpido de teólogos, historiadores y peregrinos de la fe que visitan el complejo para orar en sus naves excavadas en la roca viva.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15061','religioso','Ermita de Nuestra Señora de la Guía de Ortigueira','Fiestas grandes de la Virgen en septiembre, destacando la procesión marítimo-terrestre donde la imagen es embarcada y escoltada por la flota pesquera tradicional de la ría, acompañada de preces tradicionales de los marineros y salvas.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28012','religioso','Iglesia Parroquial de Santa María de Vilalba e Altar del Santo Cristo de la Cadena','Fiestas patronales del Cristo en septiembre, destacando los viacrucis solemnes de origen bajomedieval por su casco urbano, donde las cuadrillas de labriegos de la Terra Chá acuden a pie portando promesas silenciosas y velas exvoto en cumplimiento de mandas de salud.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37323','religioso','Ermita de la Virgen de los Remedios del Castillo de Buen Amor','Romerías estacionales tradicionales de las gentes del campo de la Armuña y visitas litúrgico-culturales organizadas a la capilla palaciega fortificada mudéjar durante las festividades marianas en el mes de septiembre, portando velas exvoto.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23018','religioso','Iglesia Parroquial de la Encarnación y Capilla del Santísimo Cristo de El Mármol','Fiestas patronales del 27 de febrero al 1 de marzo. El acto cumbre es la sobrecogedora procesión nocturna del Cristo de El Mármol a hombros por las empinadas calles del casco histórico serrano, donde miles de fieles de Sierra Mágina caminan portando pesadas cadenas en los tobillos y descalzos en cumplimiento de promesas de salud.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23044','religioso','Iglesia de la Inmaculada Concepción e Santuario de la Virgen de la Fuensanta','Romería de la Virgen de la Fuensanta el primer domingo de mayo. Las cuadrillas de labriegos y hermandades ecuestres descienden por los olivares hasta el santuario rural elevado, cumpliendo el rito inmaterial de ungirse con el agua que brota del manantial del altar mayor y depositando exvotos de cera.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18182','religioso','Santuario de Nuestra Señora del Martirio (Colegiata de Ugíjar)','Fiestas patronales del 10 al 14 de octubre. El día central (14 de octubre) destaca por la multitudinaria procesión de gloria de la Virgen del Martirio por las calles de la villa, atrayendo a decenas de miles de fieles de toda la Alpujarra granadina y almeriense que participan en el rezo tradicional de los gozos y portan velas monumentales.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90037','religioso','Iglesia Parroquial de San Patricio y Altar Popular del "Santiño del Litoral"','Festividad de San Patricio el 17 de marzo, con solemnes traslados capitulares y procesiones que custodian su efigie por el casco histórico, acompañada de ofrendas tradicionales de los labriegos y pescadores de la costa oriental granadina en cumplimiento de promesas de salud.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39018','religioso','Iglesia de Santa María de Yermo','Romerías estacionales tradicionales de las gentes del valle del Besaya y visitas litúrgico-culturales organizadas al templo románico pleno para orar ante sus relieves iconográficos medievales durante las festividades de la Natividad de la Virgen en septiembre.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39052','religioso','Santuario de la Virgen de la Valencia y Procesión de los Picayos','Festividad de la Virgen de la Valencia el 8 de septiembre (Declarada de Interés Turístico). Miles de romeros de los valles del Pas acuden a pie subiendo por las colinas hasta la pradera del santuario barroco, destacando la tradicional danza de los picayos ejecutada por jóvenes cofrades y romances sacros antiguos.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('36013','religioso','Ermita de la Virgen de la Saleta de Vilalonga e Iglesia de San Pedro','La romería mayor se celebra el 19 de septiembre. Riadas de miles de fieles del litoral de las Rías Baixas colapsan el entorno del santuario costero; se realizan procesiones donde los afectados pasan pañuelos e imágenes por el altar de la Virgen, cumpliendo el rito obligatorio de encender cirios monumentales exvoto en cumplimiento de promesas familiares de salud.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('36018','religioso','Real Monasterio de Santa María de Aciveiro','Romerías tradicionales y goteo constante de fieles que acuden al cenobio cisterciense románico restaurado para realizar el rito etnográfico obligatorio de frotar prendas textiles por las piedras del presbiterio y depositarlas exvoto para obtener la bendición de la salud familiar.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('32057','religioso','Monasterio de Santa Cristina de Ribas de Sil','Romería tradicional el 29 de junio, con la celebración de liturgias que conmemoran la antigüedad del eremitorio benedictino en pleno corazón de la Ribeira Sacra, atrayendo anualmente a teólogos, historiadores y peregrinos de la fe que visitan el complejo para orar en sus naves medievales.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('01017','religioso','Monasterio de San Juan de Caaveiro','Goteo constante e ininterrumpido de peregrinos y buscadores espirituales de Europa Occidental que visitan el complejo para orar en sus naves medievales. Celebración de misas solemnes en el crucero del templo monástico durante las festividades tradicionales del santo en el mes de junio.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('01014','religioso','Iglesia de Santa María a Nova de Noia e Cementerio de Lápidas Guildistas','Festividad de la Virgen en agosto con solemnes liturgias de las cofradías de marineros y traslados tradicionales. Durante todo el año registra un flujo continuo de peregrinos del Camino de Santiago de la Ría de Muros y Noia que visitan el monumental complejo sepulcral.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90549','religioso','Iglesia Parroquial de San Juan de Castro de Rei e Altar del "Santo Santero del Miño"','Festividad de San Juan el 24 de junio, destacando la romería tradicional de los pueblos de la Terra Chá, donde los fieles realizan el rito de verter agua sobre las extremidades enfermas y depositar exvotos de cera en cumplimiento de promesas familiares de salud.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37001','religioso','Iglesia Parroquial de Nuestra Señora de la Asunción e Ermita del Santísimo Cristo del Refugio','Función Principal y procesión solemne el 1 de mayo. El Cristo del Refugio es procesionado rodeado de miles de velas exvoto y promesas en silencio de cofrades ataviados con los trajes tradicionales de choricero de origen bajomedieval que recorren las empinadas calles con regaderas de agua tradicionales de la villa.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37012','religioso','Iglesia Parroquial de San Martín de Tours e Ermita de Nuestra Señora del Socorro','Fiestas patronales del 8 al 10 de septiembre. El acto central es la procesión de la Virgen del Socorro, enmarcada en unas fiestas de honda raigambre histórica donde los cofrades y jinetes lucen vestimentas charras medievales tradicionales, con la tradicional subasta de banzos exvoto por el casco histórico intacto (declarado conjunto histórico).','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('13066','religioso','Santuario de Nuestra Señora de los Santos de Pozuelo de Calatrava e Iglesia de San Juan Bautista','Romería de la Virgen de los Santos el primer fin de semana de mayo y a principios de septiembre. Miles de personas de toda la comarca del Campo de Calatrava acuden a pie por las veredas agrarias hasta el santuario rural elevado, cumpliendo el rito inmaterial de rezar solemnes preces tradicionales y participar en las comidas de hermandad.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16113','religioso','Santuario de Nuestra Señora de la Consolación de Iniesta e Iglesia Parroquial de la Asunción','La célebre Romería de la Virgen de la Consolación se celebra el domingo de Pentecostés. Miles de personas de toda la comarca acuden en carretas procesionales tradicionales y desfiles ecuestres, trasladando la imagen mariana desde su santuario de la dehesa hasta el centro urbano en un ambiente de hondo fervor popular.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45061','religioso','Iglesia de San Miguel, Convento de la Encarnación y Ermita de la Inmaculada Concepción','Fiestas patronales del Cristo de la Almoradilla en septiembre, destacando la multitudinaria e imponente bajada de la imagen por el escarpado casco urbano fortificado medieval (declarado conjunto histórico), acompañada de ofrendas tradicionales de los labriegos de la comarca.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03035','religioso','Santuario de Nuestra Señora de Loreto del Castillo-Fortaleza de Santa Pola e Iglesia de la Asunción','Fiestas patronales de la Virgen en septiembre, destacando la tradicional procesión marítimo-terrestre donde la imagen es embarcada y escoltada por toda la flota pesquera en alta mar, acompañada de preces tradicionales de los marineros y salvas de avancarga en cumplimiento de promesas.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12079','religioso','Ermita de la Virgen de los Desamparados de Montanejos e Iglesia Parroquial de Santiago Apóstol','Festividad de la Virgen en septiembre, destacando la romería comarcal caracterizada por el rezo de preces tradicionales y el cumplimiento del rito de bañarse los pies en el manantial de aguas medicinales sagradas termales exvoto para obtener la bendición agraria y la salud física.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46019','religioso','Santuario de Nuestra Señora de l''Oreto de l''Alcudia e Iglesia Parroquial de San Andrés Apóstol','Fiestas mayores en la primera quincena de septiembre, destacando la procesión de gloria de la Virgen sobre alfombras de sal coloreada que cubren el casco antiguo medieval, con la tradicional ofrenda de frutos de las cooperativas agrícolas en acción de gracias por la protección de las huertas.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50240','religioso','Real Monasterio de Nuestra Señora de Rueda','Flujo constante de peregrinos culturales y de fe a lo largo de todo el año. Celebración de misas solemnes en el crucero del templo monástico cisterciense durante las grandes solemnidades del año litúrgico y romerías locales de los pueblos circundantes de la Ribera Baja del Ebro.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22208','religioso','Iglesia Parroquial de Santa Cilia e Ermita de la Virgen de la Peña','Romería de la Virgen de la Peña el último domingo de mayo. Las cuadrillas de labriegos de la comarca de la Jacetania acuden a pie subiendo por las escarpadas laderas montañosas hasta el santuario del cerro elevado, portando pesadas velas exvoto en cumplimiento de promesas familiares de salud.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44153','religioso','Iglesia Parroquial de la Natividad de Nuestra Señora e Ermita de la Virgen de la Vega','Fiestas patronales de la Virgen de la Vega en septiembre, destacando la tradicional bajada de la imagen desde su ermita por el casco urbano bajo el repique manual de las campanas tradicionales, acompañada de ofrendas de las cooperativas agrícolas de la comarca del Valle del Jiloca.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33041','religioso','Ermita de la Virgen de la Barca de Navia e Iglesia de Santa María de la Barca','Fiestas grandes de la Virgen en agosto, destacando la procesión marítimo-terrestre donde la imagen es embarcada y escoltada por la flota pesquera tradicional de la ría, acompañada de preces tradicionales de los marineros y salvas.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39020','religioso','Iglesia de Santa María de la Asunción e Ermita de la Virgen de la Guía de Castro-Urdiales','Romería de la Virgen de la Guía el 15 de agosto. Destaca la procesión tradicional que traslada la imagen por el casco histórico monumental, escoltada por las hermandades de pescadores tradicionales que cantan los romances sacros medievales de los picayos bajo el sonido de las castañuelas.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('36050','religioso','Ermita de la Virgen de la Asunción de Salvaterra e Fuente de Aguas Sagradas','Romería tradicional de sanación en torno al 15 de agosto, coincidiendo con la Asunción de la Virgen. Miles de peregrinos gallegos y de las regiones fronterizas de Portugal cumplen el rito etnográfico obligatorio de lavarse con el agua del manantial de aguas medicinales sagradas exvoto para obtener la curación física.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15051','religioso','Iglesia de San Vicente de Meá e Ermita de la Virgen de la O de Mugardos','Fiestas grandes de la Virgen el 18 de diciembre, destacando la multitudinaria procesión por el casco costero, donde las hermandades de marineros tradicionales participan portando promesas silenciosas y velas exvoto en cumplimiento de mandas de salud familiar.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90553','religioso','Iglesia Parroquial de Santa María de Cospeito e Altar del "Santo Santero de la Terra Chá"','Festividad de Santa María en septiembre, destacando la romería tradicional de los pueblos de la Terra Chá, donde los fieles realizan el rito de verter agua sobre las extremidades enfermas y depositar exvotos de cera en cumplimiento de promesas familiares de salud.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37305','religioso','Ermita de la Virgen de los Dolores de Sequeros e Iglesia de San Sebastián','Fiestas patronales de la Virgen de los Dolores del 8 al 10 de septiembre. El acto central es la procesión de la Virgen, enmarcada en unas fiestas de honda raigambre histórica donde los cofrades tradicionales lucen vestimentas charras medievales tradicionales, con la tradicional subasta de banzos exvoto.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23096','religioso','Iglesia Parroquial de la Natividad de Nuestra Señora y Ermita de Santa Potenciana','Fiestas patronales y romería en honor a Santa Potenciana el segundo domingo de mayo. La imagen es trasladada desde su ermita fluvial a orillas del Guadalquivir hasta el casco urbano, acompañada de carrozas tradicionales y salvas de cohetes como cumplimiento de promesas de salud.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18035','religioso','Iglesia Parroquial de Santa Ana e Ermita del Santo Cristo de la Salud','Fiestas grandes en honor al Cristo de la Salud del 5 al 9 de octubre. Destaca la multitudinaria procesión por las empinadas calles de origen islámico, donde miles de files de toda la comarca alpujarreña granadina y almeriense participan portando velas exvoto monumentales en cumplimiento de mandas por graves dolencias.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39095','religioso','Ermita de la Virgen de la Guía de Prellezo','Romerías estacionales tradicionales de las gentes de los valles del Nansa y del Deva, con el día grande a mediados de agosto. Los devotos suben a pie hasta la ermita fortificada entonando romances sacros antiguos y portando velas en cumplimiento de promesas familiares de salud.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39012','religioso','Iglesia Parroquial de San Martín e Ermita de la Virgen de la Peña','Fiestas patronales de la Virgen de la Peña en septiembre, destacando la tradicional procesión que traslada la imagen por el casco histórico, escoltada por las hermandades tradicionales que cantan los romances sacros medievales de los picayos bajo el sonido de las castañuelas.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('36030','religioso','Iglesia de Santa María de Gargamala e Santuario de la Virgen de la Franqueira','Tres grandes romerías anuales: el lunes de Pentecostés (Pascuilla), el 8 de septiembre (fiesta grande) y el día posterior. Destaca el ancestral e impactante rito inmaterial de la representación de los dramas sacros tradicionales (el Milagro de la Fuente y la lucha del moro y el cristiano) ejecutados por varones delante de la imagen de la Virgen, acompañada de carros tirados por bueyes que portan ofrendas.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19066','religioso','Iglesia de Santa Cristina de Valeixe e Santuario de la Virgen de la Franqueira','Tres grandes romerías anuales: el lunes de Pentecostés (Pascuilla), el 8 de septiembre (fiesta grande) y el día posterior. Destaca el ancestral e impactante rito inmaterial de la representación de los dramas sacros tradicionales (el Milagro de la Fuente y la lucha del moro y el cristiano) ejecutados por varones delante de la imagen de la Virgen, acompañada de carros tirados por bueyes que portan ofrendas.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('32037','religioso','Santa María de Xunqueira de Espadanedo (Monasterio Cisterciense)','Flujo constante de peregrinos culturales y de fe a lo largo de todo el año. Celebración de misas solemnes en el crucero del templo monástico durante las grandes solemnidades del año litúrgico y romerías locales de los pueblos circundantes del alto del municipio en el mes de julio, portando velas exvoto.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('32049','religioso','Santa María de Montederramo (Monasterio Cisterciense)','Flujo constante de peregrinos culturales y de fe a lo largo de todo el año. Celebración de misas solemnes en el crucero del templo monástico durante las grandes solemnidades del año litúrgico y romerías locales de los pueblos circundantes del alto del municipio en el mes de julio, portando velas exvoto.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15062','religioso','Iglesia de San Juan de Sabardes e Ermita de la Virgen de la O de Outes','Fiestas grandes de la Virgen el 18 de diciembre (Fiesta de la Expectación), destacando la multitudinaria procesión por el casco costero, donde las hermandades de marineros y mariscadoras tradicionales participan portando promesas silenciosas y velas exvoto en cumplimiento de mandas de salud.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('01018','religioso','Santuario de Nuestra Señora de Guadalupe de Rianxo e Iglesia de Santa Comba','Fiestas de la Virgen de Guadalupe en septiembre, considerada una de las citas de piedad popular costera más populosas de la ría de Arousa. El acto cumbre es la multitudinaria procesión marítima nocturna iluminada con bengalas donde la Virgen es embarcada, cantándose de forma masiva por millares de fieles el himno tradicional de la "Rianxeira" en su honor.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27031','religioso','Real Monasterio de San Vicente del Pino e Iglesia de la Región','Fiestas de la patrona el martes de Pascua de Resurrección y el 15 de agosto, destacando la tradicional "Procesión de los Votos", rito municipal eclesiástico del siglo XIV donde el ayuntamiento acude de forma corporativa.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27057','religioso','Monasterio de la Magdalena (Padres Mercedarios) e Iglesia de San Salvador','Fiestas patronales del San Juan en junio y solemnes cultos de los Remedios en septiembre. Goteo ininterrumpido y diario de miles de peregrinos de la ruta del Camino de Santiago Francés (siendo Sarria el punto de inicio de masas obligatorio para obtener la Compostela), quienes pernoctan en la villa y rinden culto en sus naves medievales.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37014','religioso','Ermita de Nuestra Señora de la Asunción de Aldeadávila e Iglesia Parroquial de San Salvador','Fiestas patronales de la Virgen de la Asunción del 22 al 28 de agosto, destacando la tradicional bajada de la imagen desde su ermita serrana hasta la parroquia para la celebración de su novena, congregando a miles de fieles de la comarca fronteriza con Portugal.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23030','religioso','Iglesia Parroquial de Nuestra Señora de la Paz y Ermita de la Virgen de la Paz (Las Infantas)','Fiestas patronales y romería del 24 al 26 de enero. Los files de las cuencas olivareras del Alto Guadalquivir realizan marchas a pie nocturnas y guardan largas colas para cumplir el rito etnográfico obligatorio de untarse con el aceite bendecido de sus lámparas exvoto en cumplimiento de promesas familiares de salud.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23080','religioso','Ermita de la Virgen de los Remedios y Parajes de Sanación de la Campiña','Romería tradicional el primer domingo de mayo, coincidiendo con las rogativas de las dehesas. Labriegos de las cuencas del olivar del Alto Guadalquivir realizan traslados procesionales y marchas a pie nocturnas, cumpliendo el rito inmaterial de ungirse con el aceite de las lámparas votivas en busca de la salud de las familias agrícolas.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18183','religioso','Iglesia Parroquial de San José y Ermita del Santo Cristo de la Yedra','Fiestas grandes en honor al Cristo de la Yedra del 14 al 17 de septiembre. Destaca la multitudinaria procesión por las empinadas calles de origen islámico, donde miles de files de toda la comarca alpujarreña granadina y almeriense participan portando velas exvoto monumentales en cumplimiento de mandas por graves dolencias.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18076','religioso','Iglesia Parroquial de Nuestra Señora de la Anunciación y Ermita de la Virgen de los Dolores','Fiestas patronales del 6 al 11 de septiembre en honor a la Virgen de los Dolores. Destaca la tradicional ofrenda de cirios monumentales exvoto y la procesión claustral por las naves y el claustro medieval bajo el canto solemne de preces tradicionales.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39091','religioso','Ermita de la Virgen de la Guía de Lamadrid','Romerías estacionales tradicionales de las gentes de los valles del Nansa y del Deva, con el día grande a mediados de agosto. Los devotos suben a pie hasta la ermita fortificada entonando romances sacros antiguos y portando velas en cumplimiento de promesas familiares de salud.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90537','religioso','Santuario de Nuestra Señora de la Saleta de Barcia de Mera','La gran romería se celebra el 19 de septiembre, considerada una de las manifestaciones de piedad popular santera y exorcista más impresionantes del sur de Galicia. Riadas de miles de fieles de toda la provincia colapsan el santuario montañoso; se realizan procesiones donde los afectados gritan preces de liberación y pasan pañuelos e imágenes por el altar de la Virgen.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('32036','religioso','Real Colegiata e Monasterio de Santa María de Xunqueira de Ambía','Festividad del santo en agosto con solemnes liturgias de los viticultores locales y traslados tradicionales, destacando la apertura del templo para la veneración de las reliquias mayores y el rezo tradicional de los gozos en gallego.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15042','religioso','Iglesia de San Juan de Lousame e Ermita de la Virgen de la O de Lousame','Fiestas grandes de la Virgen el 18 de diciembre (Fiesta de la Expectación), destacando la multitudinaria procesión por el casco costero, donde las hermandades de marineros y mariscadoras tradicionales participan portando promesas silenciosas y velas exvoto en cumplimiento de mandas de salud.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90007','religioso','Santuario de Nuestra Señora de Loreto de Porto do Son e Iglesia de San Vicente','Fiestas de la Virgen de Guadalupe en septiembre, considerada una de las citas de piedad popular costera más populosas de la ría de Arousa. El acto cumbre es la multitudinaria procesión marítima nocturna iluminada con bengalas donde la Virgen es embarcada, cantándose de forma masiva por millares de fieles el himno tradicional de la "Rianxeira" en su honor.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27050','religioso','Real Monasterio de San Vicente de Quiroga e Iglesia de la Región','Fiestas de la patrona el martes de Pascua de Resurrección y el 15 de agosto, destacando la tradicional "Procesión de los Votos", rito municipal eclesiástico del siglo XIV donde el ayuntamiento acude de forma corporativa.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27051','religioso','Monasterio de la Magdalena (Padres Mercedarios) e Iglesia de San Salvador de Ribadeo','Fiestas patronales del San Juan en junio y solemnes cultos de los Remedios en septiembre. Goteo ininterrumpido y diario de miles de peregrinos de la ruta del Camino de Santiago, quienes pernoctan en la villa y rinden culto en sus naves medievales.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37272','religioso','Ermita de Nuestra Señora de la Asunción de Saelices e Iglesia Parroquial de San Salvador','Fiestas patronales de la Virgen de la Asunción del 22 al 28 de agosto, destacando la tradicional bajada de la imagen desde su ermita serrana hasta la parroquia para la celebración de su novena, congregando a miles de fieles de la comarca fronteriza con Portugal.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37279','religioso','Ermita de la Virgen de la Vega de Sancti-Spíritus e Iglesia de San Martín','Romería de la Virgen de la Vega el segundo domingo de mayo. Las cuadrillas de labriegos de la comarca del campo charro acuden a pie portando pesadas velas exvoto y carros tradicionales en cumplimiento de promesas familiares de salud agrícola y bendición de las dehesas.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23047','religioso','Iglesia Parroquial de la Inmaculada Concepción y Santuario de la Virgen de la Cabeza de La Iruela','Fiestas patronales y romería del 10 al 15 de agosto. Destaca la tradicional bajada de la imagen mariana por las empinadas veredas rocosas a las faldas del imponente castillo fortificado, con salvas de pólvora continuas y un riguroso rezo de preces tradicionales por la salud rural.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23066','religioso','Iglesia de Nuestra Señora de la Encarnación y Santuario de la Virgen de la Encina','Romería de la Virgen de la Encina el primer domingo de mayo. Las carretas y fieles de la cuenca olivarera descienden por los campos de labranza hasta el santuario rural elevado, cumpliendo el rito tradicional de las subastas de los banzos exvoto para portar la imagen.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18046','religioso','Iglesia Parroquial de Nuestra Señora de los Ángeles y Ermita del Santo Cristo de la Veracruz','Fiestas mayores en honor al Cristo de la Veracruz el primer fin de semana de octubre. Destaca la multitudinaria procesión por el casco histórico de origen islámico colgado sobre el barranco del río, donde miles de files de las sierras del norte granadino participan en estricto silencio nocturno.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18152','religioso','Iglesia Parroquial de la Anunciación y Ermita de la Virgen de los Dolores','Fiestas patronales del 6 al 11 de septiembre en honor a la Virgen de los Dolores. Destaca la tradicional ofrenda de cirios monumentales exvoto y la procesión claustral por las naves y el claustro medieval bajo el canto solemne de preces tradicionales de la comarca de Los Montes.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39061','religioso','Ermita de la Virgen de Latas','La célebre Romería de la Virgen de Latas se celebra el 8 de septiembre, compartida históricamente con el municipio vecino de Marina de Cudeyo. Destaca la espectacular procesión marítima por las aguas de la bahía, donde la imagen es desembarcada y escoltada por centenares de files portando velas en cumplimiento de promesas familiares de salud.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39040','religioso','Iglesia Parroquial de San Roque e Ermita de la Virgen de los Remedios','Fiestas patronales de la Virgen de los Remedios en septiembre, destacando la tradicional procesión que traslada la imagen por el casco histórico, escoltada por las hermandades tradicionales que cantan los romances sacros medievales de los picayos bajo el sonido de las castañuelas.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('36004','religioso','Santuario de los Milagros de Fefiñáns','La gran romería se celebra el segundo domingo de septiembre, considerada la manifestación de piedad mariana más masiva del interior de la provincia, reuniendo a más de 50.000 fieles que realizan marchas penitenciales a pie durante toda la noche desde la capital y las comarcas vecinas, destacando el tradicional e impactante rito inmaterial de las promesas que se cumplen portando pesadas mortajas.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('36028','religioso','Ermita de la Virgen de los Dolores de Paradela e Iglesia de Santa María','La romería mayor se celebra el segundo domingo de septiembre. Riadas de miles de fieles del interior de la provincia colapsan el entorno del santuario; se realizan procesiones donde los afectados pasan pañuelos e imágenes por el altar de la Virgen, cumpliendo el rito obligatorio de encender cirios monumentales exvoto en cumplimiento de promesas familiares de salud mental y liberación.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('32076','religioso','Real Monasterio de Santa María la Real de Oseira (Eje HistóricoReliquioso)','Festividad de la Virgen en agosto con solemnes liturgias de la comunidad de monjes Cistercienses de la Estricta Observancia (Trapenses). Goteo ininterrumpido y diario de peregrinos internacionales de la ruta del Camino de Santiago Sanabrés que visitan el monumental complejo capitular para la oración contemplativa, portando velas exvoto monumentales.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15901','religioso','Santuario de San Antón de Corveiro e Iglesia de San Bartolomé','Fiestas de San Antón en septiembre, considerada una de las citas de piedad popular costera más populosas de la ría de Ortigueira. El acto cumbre es la multitudinaria procesión marítima nocturna iluminada con bengalas donde la Virgen y el santo son embarcados, cantándose de forma masiva por millares de fieles himnos tradicionales en su honor.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90547','religioso','Real Monasterio de San Vicente de Bóveda e Iglesia de la Región','Fiestas de la patrona el martes de Pascua de Resurrección y el 15 de agosto, destacando la tradicional "Procesión de los Votos", rito municipal eclesiástico del siglo XIV donde el ayuntamiento acude de forma corporativa.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27040','religioso','Iglesia Monacal de San Salvador de Vilar de Donas','Fiestas patronales del Salvador en agosto y solemnes cultos tradicionales. Goteo ininterrumpido y de carácter diario de miles de peregrinos de la ruta del Camino de Santiago Francés, quienes visitan el monumental complejo románico para orar ante sus célebres frescos góticos del siglo XIV.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37164','religioso','Ermita de Nuestra Señora de la Asunción de Huerta e Iglesia Parroquial de San Salvador','Fiestas patronales de la Virgen de la Asunción del 22 al 28 de agosto, destacando la tradicional bajada de la imagen desde su ermita serrana hasta la parroquia para la celebración de su novena, congregando a miles de fieles de la comarca agraria.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23046','religioso','Iglesia Parroquial de San Pedro Apóstol y el Señor del Santuario','Fiestas grandes el primer fin de semana de mayo, con solemnes traslados capitulares y procesiones que custodian la efigie por el centro urbano. Los files del olivar participan en una solemne liturgia y cumplen el rito etnográfico obligatorio de frotar pañuelos por el altar en cumplimiento de mandas familiares de salud.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18164','religioso','Ermita de la Virgen de la Cabeza de la Puebla e Iglesia de Santa María de la Quinta Angustia','Romería de las Santas el lunes de Pentecostés. Las imágenes de las niñas mártires son trasladadas a pie desde la monumental parroquia del centro urbano hasta el santuario de alta montaña al pie de la Sierra de la Sagra, en un rito de hermandad compartido con la vecina localidad de Huéscar mediante un régimen de concordia canónica por el cual las imágenes permanecen cincuenta días en cada pueblo.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18082','religioso','Iglesia Parroquial de Nuestra Señora de la Anunciación y Ermita de la Virgen de la Cabeza de Galera','Fiestas patronales del 2 al 6 de agosto. El acto central destaca por la solemne procesión de la Virgen de la Cabeza por las calles del centro histórico de origen islámico y cuevas, acompañada de promesas tradicionales y marchas silenciosas a pie de los agricultores de la comarca.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39025','religioso','Santuario de Nuestra Señora de las Caldas','Gran romería el 15 de agosto. Reúne a decenas de miles de romeros de los valles del Besaya que acuden a pie subiendo por las colinas hasta la pradera del santuario barroco, destacando las procesiones tradicionales y el repique manual de campanas.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39041','religioso','Iglesia Parroquial de San Martín e Ermita de la Virgen de la Peña','Fiestas patronales de la Virgen de la Peña en septiembre, destacando la tradicional procesión que traslada la imagen por el casco histórico, escoltada por las hermandades tradicionales que cantan los romances sacros medievales de los picayos bajo el sonido de las castañuelas.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('36032','religioso','Santuario de los Milagros de Amil','La gran romería se celebra el segundo domingo de septiembre, considerada la manifestación de piedad mariana más masiva del interior de la provincia, reuniendo a más de 50.000 fieles que realizan marchas penitenciales a pie durante toda la noche desde la capital y las comarcas vecinas, destacando el tradicional e impactante rito inmaterial de las promesas que se cumplen portando pesadas mortajas.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15034','religioso','Ermita de la Virgen del Monte de O Ézaro e Iglesia de Santa Uxía','Fiestas grandes de la Virgen en septiembre, destacando la multitudinaria procesión por el casco costero, donde las hermandades de marineros y mariscadoras tradicionales participan portando promesas silenciosas y velas exvoto en cumplimiento de mandas de salud familiar junto a la espectacular cascada fluvial.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15043','religioso','Santuario de San Adrián de Malpica e Iglesia de Santiago','Fiestas de San Adrián en junio, considerada una de las citas de piedad popular costera más populosas de la comarca de Bergantiños. El acto cumbre es la multitudinaria procesión marítima nocturna iluminada con bengalas donde la imagen es desembarcada, cantándose de forma masiva por millares de fieles himnos tradicionales en su honor.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27032','religioso','Monasterio de la Magdalena (Padres Mercedarios) e Iglesia de San Salvador de Monterroso','Fiestas patronales del San Juan en junio y solemnes cultos de los Remedios en septiembre. Goteo ininterrumpido y diario de miles de peregrinos de la ruta del Camino de Santiago, quienes pernoctan en la villa y rinden culto en sus naves medievales.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37136','religioso','Ermita de la Virgen de la Vega de Fuenteguinaldo e Iglesia de San Juan','Romería de la Virgen de la Vega el segundo domingo de mayo. Las cuadrillas de labriegos de la comarca del campo acuden a pie portando pesadas velas exvoto y carros tradicionales en cumplimiento de promesas familiares de salud agrícola y bendición de las tierras.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23059','religioso','Ermita de Nuestra Señora de la Paz y los Balnearios Sagrados del río Guadalquivir','Festividad de la Virgen de la Paz en torno al 24 de enero, con procesión de gloria por el casco histórico, y una popular romería primaveral a pie donde las cofradías olivareras de la Campiña de Jaén acuden a presentar sus promesas e iluminar el manantial con velas exvoto.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18105','religioso','Iglesia Parroquial de Nuestra Señora de los Remedios y Ermita de la Virgen de los Dolores','Fiestas patronales en la segunda quincena de agosto, destacando la multitudinaria procesión por las empinadas calles bajo el volteo manual de campanas. Los fieles realizan marchas a pie desde los cortijos y guardan largas colas para acceder a besar el pie de la imagen mariana en cumplimiento de promesas de salud.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39019','religioso','Colegiata de Santa Cruz de Castañeda','Romerías estacionales tradicionales de las gentes del valle del Pas y visitas litúrgico-culturales organizadas al templo románico pleno durante las grandes solemnidades del año litúrgico, portando pesadas velas exvoto y participando en los cantos de romances sacros antiguos.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('36003','religioso','Ermita de la Virgen de los Dolores de Beluso e Iglesia de Santa María','Fiestas mayores en la primera quincena de septiembre, destacando la multitudinaria procesión marítimo-terrestre donde las alfombras florales cubren el casco costero y la imagen es embarcada y escoltada por la flota pesquera tradicional de la ría en cumplimiento de promesas.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15087','religioso','Santuario de la Virgen del Porto de Valdoviño e Iglesia de Santiago','Fiestas de la Virgen en septiembre, considerada una de las citas de piedad popular costera más populosas de la comarca de Ferrolterra. El acto cumbre es la multitudinaria procesión marítima nocturna iluminada con bengalas donde la Virgen es desembarcada, cantándose de forma masiva por millares de fieles himnos tradicionales en su honor.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37009','religioso','Iglesia Parroquial de Nuestra Señora de las Nieves e Ermita de la Virgen de la Soledad','Fiestas patronales del 5 al 10 de agosto. El acto central es la procesión de la Virgen de las Nieves, enmarcada en unas fiestas de honda raigambre histórica donde los cofrades y jinetes lucen vestimentas charras medievales tradicionales, con la tradicional subasta de banzos exvoto por el casco histórico intacto (declarado conjunto histórico).','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24086','religioso','Iglesia Parroquial de Santo Domingo de Guzmán y Ermita del Santo Cristo de la Columna','Fiestas patronales del 20 al 24 de septiembre. Destaca la multitudinaria procesión nocturna del Cristo a hombros por las escarpadas pendientes de Sierra Mágina, acompañada por el encendido de "luminarias" tradicionales de fuego en los cerros y mandas de promesas descalzas por la salud.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90028','religioso','Iglesia Parroquial de San Julián y Santa Basilisa e Ermita de los Remedios','Fiestas patronales de la Virgen de los Remedios en septiembre, destacando la procesión tradicional que traslada la imagen por el casco medieval fortificado, escoltada por las cofradías tradicionales que cantan los romances sacros de los picayos bajo el repique manual de campanas.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('36020','religioso','Ermita de Nuestra Señora de los Desamparados de Agolada e Iglesia de San Pedro','Romería de la Virgen el segundo domingo de mayo, congregando a las cuadrillas de labriegos y files de la Galicia interior que acuden a pie por las veredas tradicionales, destacando las procesiones alrededor del santuario y las promesas que se cumplen portando pesadas velas exvoto.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15044','religioso','Ermita de la Virgen del Carmen de O Barqueiro e Iglesia de Santiago','Fiestas grandes de la Virgen en agosto, destacando la procesión marítimo-terrestre donde la imagen es embarcada y escoltada por la flota pesquera tradicional de la ría, acompañada de preces tradicionales de los marineros y salvas.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27058','religioso','Iglesia Monacal de Santo Estevo de Ribas de Miño','Fiestas patronales en enero y solemnes cultos tradicionales en honor a la Virgen en septiembre. Goteo ininterrumpido de peregrinos y buscadores espirituales de Europa Occidental que visitan el monumental complejo románico para orar ante sus relieves capitulares y ábsides medievales calados.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90541','religioso','Ermita de la Virgen de los Dolores de Arcade e Iglesia de Santiago','Fiestas mayores en la primera quincena de septiembre, destacando la multitudinaria procesión marítimo-terrestre donde las alfombras florales cubren el casco costero y la imagen es embarcada y escoltada por la flota pesquera tradicional de la ría en cumplimiento de promesas.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23019','religioso','Santuario de Nuestra Señora de la Cabeza de Campillo e Iglesia de la Encarnación','Las fiestas patronales y la Romería se celebran en torno al segundo domingo de agosto. El acto central destaca por la espectacular procesión y las tradicionales escaramuzas teatrales de las "Fiestas de Moros y Cristianos", rito inmaterial donde las cuadrillas de labriegos y files de Sierra Mágina Occidental se disputan el paso de la Virgen entre estruendosas salvas de pólvora.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18138','religioso','Iglesia Parroquial de Nuestra Señora de las Angustias y Ermita del Santo Cristo de la Salud','Fiestas grandes en honor al Cristo de la Salud el último fin de semana de agosto. Destaca la multitudinaria bajada nocturna iluminada con hachones, atrayendo a miles de files y jornaleros de la comarca de Loja que realizan marchas a pie por las veredas de secano y presentan fotografías de enfermos en su altar.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39048','religioso','Santuario de Nuestra Señora de los Remedios de Penagos e Iglesia de San Jorge','Gran romería el 25 de marzo, atrayendo a miles de romeros de las comunidades del entorno pasiego que ascienden a pie por las veredas. Se celebra la bendición de los ganados y campos en las campas altas, acompañada por el canto tradicional de romances sacros antiguos delante de la imagen.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('36005','religioso','Iglesia de San Cibrán de Aldán e Santuario de la Virgen del Carmen','Celebraciones grandes el último fin de semana de julio, destacando la multitudinaria procesión marítimo-terrestre donde la imagen es embarcada y escoltada por la flota pesquera artesanal en alta mar, acompañada de tradicionales ofrendas de fuego e hachones de resina en los muelles en cumplimiento de promesas.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18066','religioso','Iglesia Parroquial de San Martín y la Ermita del Santo Cristo de la Veracruz','Fiestas grandes en honor al Cristo de la Veracruz a mediados de agosto, destacando la multitudinaria e imponente bajada nocturna iluminada con antorchas. Los fieles realizan marchas a pie descalzos desde los cortijos de la Vega de Granada y guardan largas colas para acceder a presentar promesas de salud y exvotos en su altar.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39028','religioso','Santuario de Nuestra Señora de la Encina de Hoznayo e Iglesia de San Juan Bautista','Festividad de la Virgen de la Encina en torno al 8 de septiembre (Declarada de Interés Turístico). Miles de romeros de los valles de la Trasmiera acuden a pie subiendo por las colinas hasta la pradera del santuario barroco, destacando la tradicional danza de los picayos ejecutada por jóvenes cofrades y romances sacros antiguos.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15092','religioso','Ermita de la Virgen del Monte de Camariñas e Iglesia de Santiago','Fiestas grandes de la Virgen en agosto, destacando la procesión marítimo-terrestre donde la imagen es embarcada y escoltada por la flota pesquera tradicional de la ría, acompañada de preces tradicionales de los marineros y salvas en las inmediaciones del cabo Vilán.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23045','religioso','Iglesia Parroquial de Nuestra Señora de la Cabeza y los Altares de Ánimas de los Cortijos de la Vega','Peregrinación estacional espontánea en los meses de mayo y agosto. Labriegos del olivar y de los huertos tradicionales del sureste de Jaén acuden a las veredas agrarias para encender hachones exvoto ante pequeñas hornacinas rústicas, orando por la salud y pidiendo protección ante las pertinaces sequías de la cuenca.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18039','religioso','Iglesia Parroquial de Santa María de la Anunciación y Ermita del Santo Cristo de los Milagros','Fiestas mayores el último fin de semana de agosto, caracterizadas por una multitudinaria bajada nocturna iluminada con antorchas. Fieles y familias completas del altiplano granadino realizan marchas a pie descalzas por las veredas de secano, portando fotografías y prendas textiles de enfermos para presentarlas ante su presbiterio.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39043','religioso','Santuario de Nuestra Señora de los Remedios de Meruelo e Iglesia de San Miguel','Festividad de la Virgen de los Remedios el 8 de septiembre (Declarada de Interés Turístico). Miles de romeros de los valles de la Trasmiera acuden a pie subiendo por las colinas hasta la pradera del santuario barroco, destacando la tradicional danza de los picayos ejecutada por jóvenes cofrades y romances sacros antiguos.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('36016','religioso','Ermita de la Virgen de los Dolores de Vilaxoán e Iglesia de San Martín','Fiestas mayores en la primera quincena de septiembre, destacando la multitudinaria procesión marítimo-terrestre donde las alfombras florales cubren el casco costero y la imagen es embarcada y escoltada por la flota pesquera tradicional de la ría en cumplimiento de promesas familiares de salud.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15045','religioso','Ermita de la Virgen del Monte de Mazaricos e Iglesia de San Juan','Fiestas grandes de la Virgen en agosto, destacando la procesión marítimo-terrestre donde la imagen es embarcada y escoltada por la flota pesquera tradicional de la ría, acompañada de preces tradicionales de los marineros y salvas en las inmediaciones de la Costa da Morte.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23088','religioso','Hornacina del Santo Cristo del Huerto y la Ruta del Rosario de las Dehesas','Goteo ininterrumpido de files procedentes de los cortijos del entorno olivarero durante el ciclo estacional de la primavera y los primeros días de septiembre. Los labriegos y jornaleros acuden a pie por las veredas agrarias para encender hachones de cera exvoto en demanda de sanidad física y protección climática para las cosechas.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18159','religioso','Iglesia Parroquial de San Pedro y Ermita de la Virgen de la Caridad','Fiestas patronales y romería en la segunda quincena de agosto. Destaca la multitudinaria bajada de la Virgen por el casco histórico de origen medieval fortificado, acompañada de subastas tradicionales de banzos y mandas a pie de los agricultores de la comarca de Los Montes.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39031','religioso','Santuario de Nuestra Señora de los Remedios de Beranga e Iglesia de San Cipriano','Festividad de la Virgen de los Remedios el 8 de septiembre. Miles de romeros de los valles de la Trasmiera acuden a pie subiendo por las colinas hasta la pradera del santuario barroco, destacando la tradicional danza de los picayos ejecutada por jóvenes cofrades y romances sacros antiguos.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('36061','religioso','Ermita de la Virgen de los Dolores de San Cibrán e Iglesia de San Cipriano','Fiestas mayores en la primera quincena de septiembre, destacando la multitudinaria procesión marítimo-terrestre donde las alfombras florales cubren el casco costero y la imagen es embarcada y escoltada por la flota pesquera tradicional de la ría en cumplimiento de promesas familiares de salud.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15093','religioso','Ermita de la Virgen del Monte de Baio e Iglesia de San Juan','Fiestas grandes de la Virgen en agosto, destacando la procesión marítimo-terrestre donde la imagen es embarcada y escoltada por la flota pesquera tradicional de la ría, acompañada de preces tradicionales de los marineros y salvas en las inmediaciones de la Costa da Morte.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23067','religioso','Ermita de la Virgen de Gracia y la Cueva de la Fuente de la Peña','Las fiestas patronales se celebran la primera semana de agosto. Destaca la multitudinaria procesión que traslada la imagen mariana por el escarpado Casco Histórico, donde los files de Sierra Mágina Occidental realizan preces tradicionales en torno a "La Charca" (estanque monumental que riega la huerta local), cumpliendo promesas de salud y acción de gracias agrícolas.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18051','religioso','Iglesia Parroquial de la Encarnación y Santuario de la Virgen de la Cabeza de Colomera','Gran romería el último domingo de abril, celebrada en paralelo a la de Andújar. Miles de peregrinos de la comarca de Los Montes Orientales y la Vega de Granada realizan marchas a pie nocturnas cruzando los senderos montañosos hasta la ermita del cerro, portando hachones exvoto y pesadas cruces de madera.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39102','religioso','Santuario de Nuestra Señora de Palacios e Iglesia de San Miguel','Festividad de la Virgen el 15 de agosto. Reunión multitudinaria de las gentes de la junta de voto que acuden en carretas tradicionales engalanadas, destacando las procesiones perimetrales por la pradera bajo el canto solemne de romances sacros medievales interpretados por cofrades locales al son de castañuelas (picayos).','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34003','religioso','Santuario de Nuestra Señora de los Remedios de Castro Caldelas e Iglesia de Santa Isabel','Fiestas grandes del 7 al 10 de septiembre, destacando la multitudinaria procesión por el casco medieval fortificado (declarado conjunto histórico) bajo las torres del castillo, donde las hermandades de viticultores tradicionales del río Sil realizan ofrendas de mosto y vino en acción de gracias por la protección de las viñas.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37313','religioso','Iglesia Parroquial de Nuestra Señora de la Asunción e Ermita de la Virgen de la Soledad','Fiestas patronales a finales de agosto, destacando la tradicional procesión de la Virgen, enmarcada en unas fiestas de honda raigambre histórica donde los cofrades y jinetes lucen vestimentas charras medievales tradicionales, con la tradicional subasta de banzos exvoto por el casco de entramado serrano intacto (declarado conjunto histórico) junto al río Alagón.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23054','religioso','Iglesia Parroquial de San Pedro Apóstol y los Altares de Rogativas del Secano','Celebración de las fiestas patronales y procesiones tradicionales a finales de junio, coincidiendo con la recogida de las cosechas del cereal. Los agricultores de la comarca de Sierra Mágina Oriental acuden al templo rústico a encender cirios exvoto monumentales, realizando promesas silenciosas y mandas a pie en demanda de lluvias y bendición agraria.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18171','religioso','Iglesia Parroquial de Santa Ana y la Ermita del Santo Cristo de la Salud','Fiestas grandes en honor al Cristo de la Salud a finales de agosto, caracterizadas por una multitudinaria e imponente bajada nocturna iluminada con antorchas. Fieles y jornaleros del Poniente Granadino realizan marchas a pie descalzas por las veredas agrarias y presentan fotografías y prendas de enfermos en su altar.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39072','religioso','Iglesia Parroquial de San Roque e Ermita de la Virgen de los Dolores','Fiestas patronales de San Roque a mediados de agosto. Destaca la tradicional romería que traslada la imagen por el escarpado paisaje montañoso, escoltada por las hermandades de pastores pasiegos que cantan los romances sacros medievales de los picayos bajo el sonido de las castañuelas y portan bastones tradicionales.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('36027','religioso','Ermita de la Virgen de los Dolores de Simes e Iglesia de Santa María','Fiestas mayores en la primera quincena de septiembre, destacando la multitudinaria procesión marítimo-terrestre donde las alfombras florales cubren el casco costero y la imagen es embarcada y escoltada por la flota pesquera tradicional de la ría en cumplimiento de promesas familiares de salud.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90428','religioso','Iglesia Parroquial de la Anunciación y Ermita de Nuestra Señora de la Cabeza de Aldeire','Romería de la Virgen el último domingo de abril (celebrada en consonancia con Andújar). Destaca la multitudinaria bajada de la efigie mariana desde su ermita serrana hasta el centro urbano, donde los files realizan promesas silenciosas y mandas a pie cruzando los senderos montañosos del Marquesado.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39037','religioso','Santuario de Nuestra Señora de la Quinta Angustia de Rucandio e Iglesia de Santa María','Festividad mayor el 15 de agosto, congregando a miles de romeros de los valles del Miera que acuden a pie subiendo por las veredas montañosas. Destaca la tradicional procesión perimetral por la pradera bajo el canto solemne de romances sacros medievales interpretados por cofrades locales al son de castañuelas (picayos).','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('36059','religioso','Monasterio de San Salvador de Camanzo','La romería mayor se celebra el segundo domingo de septiembre. Riadas de miles de fieles del interior de la provincia colapsan el entorno del monasterio; se realizan procesiones donde los afectados pasan pañuelos e imágenes por el altar de la Virgen, cumpliendo el rito obligatorio de encender cirios monumentales exvoto en cumplimiento de promesas familiares de salud mental y liberación.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90194','religioso','Ermita de Nuestra Señora del Faro de Corme e Iglesia de San Adrián','Fiestas grandes de la Virgen en septiembre, destacando la procesión marítimo-terrestre donde la imagen es embarcada y escoltada por la flota pesquera artesanal de la ría, acompañada de preces tradicionales de los marineros y salvas en las inmediaciones del cabo Roncudo.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23026','religioso','Ermita de Nuestro Padre Jesús Nazareno y los Altares de las Hazas','Goteo ininterrumpido de fieles durante las festividades de mayo y mediados de septiembre (fiestas del rezo tradicional del Rosario). Jornaleros de la cuenca del río San Juan acuden a pie por las veredas para presentar promesas de salud ante la imagen, encendiendo hachones de cera exvoto en demanda de protección para los cultivos de cerezas y olivos.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39084','religioso','Santuario de Nuestra Señora de los Remedios de Riaño e Iglesia de San Pedro','Festividad de la Virgen de los Remedios el 8 de septiembre (Declarada de Interés Turístico). Miles de romeros de los valles de la Trasmiera acuden a pie subiendo por las colinas hasta la pradera del santuario barroco, destacando la tradicional danza de los picayos ejecutada por jóvenes cofrades y romances sacros antiguos.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39056','religioso','Santuario de Nuestra Señora de la Asunción de Vargas e Iglesia de San Miguel','Gran romería el 15 de agosto. Reúne a decenas de miles de romeros de los valles del Pas que acuden a pie subiendo por las colinas hasta la pradera del santuario barroco, destacando las procesiones tradicionales y el repique manual de campanas.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23904','religioso','Iglesia Parroquial de la Asunción de Nuestra Señora y Altares de Pastores de los Campos de Hernán Perea','Goteo constante de pastores y familias del altiplano y las cumbres jiennenses durante la festividad de San Juan (24 de junio). Se realizan reuniones tradicionales e intercambios de ungüentos sacralizados con rezos, pidiendo la sanación de afecciones óseas crónicas y la bendición de los rebaños que cruzan el altiplano.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18074','religioso','Iglesia Parroquial de la Anunciación y Ermita de la Virgen de la Cabeza de Ferreira','Celebración de las fiestas patronales y romería el último fin de semana de abril. Cientos de files del Marquesado y de las vertientes de Sierra Nevada ascienden a pie escoltando la imagen mariana hasta su ermita, portando hachones exvoto y cumpliendo mandas de promesas por graves dolencias en estricto silencio.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('01005','religioso','Ermita de Nuestra Señora del Monte de Xaviña e Iglesia de San Jorge','Fiestas grandes de la Virgen en septiembre, destacando la procesión marítimo-terrestre donde la imagen es embarcada y escoltada por la flota pesquera artesanal de la ría, acompañada de preces tradicionales de los marineros y salvas en las inmediaciones de la Costa da Morte.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24018','religioso','Las Caras de Bélmez (Casa de María Gómez Cámara) y la Parroquia de Nuestra Señora de la Paz','Goteo ininterrumpido diario y picos masivos de visitantes durante las festividades de Todos los Santos (noviembre) y Semana Santa. Miles de peregrinos del misterio y fieles de corte tradicional acuden a la vivienda de la calle Real para orar, depositar estampas exvoto y rozar las imágenes impresas en el cemento del suelo.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23017','religioso','Iglesia de Nuestra Señora de la Expectación y el Lienzo del Santo Cristo de Burgos','Las fiestas mayores y solemnes rogativas se celebran en torno al 14 al 18 de agosto. Miles de files de Sierra Mágina Oriental y de la comarca granadina de Guadix acuden en peregrinación a pie cumpliendo rigurosas mandas de silencio y portando cirios exvoto monumentales para besar el lienzo y pedir protección para los olivares.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18083','religioso','Iglesia Parroquial de la Anunciación y Ermita de la Virgen de los Dolores','Fiestas patronales del 15 al 18 de agosto, destacando la tradicional bajada de la imagen desde su ermita por el casco rural bajo el volteo manual de las campanas tradicionales, acompañada de ofrendas de grano y aceite de las cooperativas agrícolas en acción de gracias por la cosecha.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39064','religioso','Santuario de Nuestra Señora de los Remedios de Riotuerto e Iglesia de San Juan Bautista','Festividad de la Virgen de los Remedios el 8 de septiembre. Miles de romeros de los valles de la Trasmiera acuden a pie subiendo por las colinas hasta la pradera del santuario barroco, destacando la tradicional danza de los picayos ejecutada por jóvenes cofrades y romances sacros antiguos.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23073','religioso','Santuario de Nuestra Señora de Tíscar y Cueva del Agua de Tíscar','Festividad máxima el primer domingo de septiembre y el 15 de agosto (La Bajada). Decenas de miles de peregrinos de las provincias de Jaén, Granada y Almería colapsan el escarpado puerto de montaña, ascendiendo descalzos y a pie por los riscos de la peña de Tíscar para postrarse ante la imagen mariana y cumplir rigurosas promesas de salud.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18137','religioso','Iglesia Parroquial de Santa Ana y la Ermita de la Virgen de la Cabeza de Montillana','Fiestas patronales del 15 al 18 de agosto, destacando la tradicional bajada de la efigie desde su ermita serrana hasta la monumental iglesia parroquial de cantería local para la celebración de su novena, congregando a miles de fieles y jornaleros de la comarca de Los Montes Orientales que portan pesadas velas exvoto.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18088','religioso','Iglesia Parroquial de Santa María Mayor y Ermita de la Virgen de Loreto','Fiestas patronales del 15 al 18 de agosto, destacando la tradicional bajada de la efigie desde su ermita serrana hasta la monumental iglesia parroquial de cantería local para la celebración de su novena, congregando a miles de fieles y jornaleros de la comarca de Los Montes Orientales que portan pesadas velas exvoto.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39100','religioso','Santuario de Nuestra Señora de la Caridad de Sandoñana e Iglesia de San Juan','Festividad de la Virgen de la Caridad el 8 de septiembre. Miles de romeros de los valles del Pas y Carriedo acuden a pie subiendo por las colinas hasta la pradera del santuario barroco, destacando la tradicional danza de los picayos ejecutada por jóvenes cofrades y romances sacros antiguos al son de castañuelas.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23043','religioso','Iglesia Parroquial de Nuestra Señora de la Asunción y Ermita de San Roque','Fiestas patronales del 15 al 18 de agosto. Destaca la solemne procesión de la Virgen y San Roque por las empinadas calles de este conjunto histórico fortificado, donde las gentes de los cortijos serranos bajan a cumplir promesas de salud y realizan subastas de banzos exvoto.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18063','religioso','Iglesia Parroquial de Nuestra Señora de la Anunciación y Ermita del Amparo','Fiestas grandes en honor al Cristo de la Luz a finales de octubre. Destaca la multitudinaria procesión por el casco rural, donde los fieles de la comarca de la Hoya de Guadix acuden portando cirios exvoto monumentales en cumplimiento de promesas familiares de salud agrícola.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39078','religioso','Santuario de Nuestra Señora de la Asunción de Santiurde e Iglesia de San Jorge','Gran romería el 15 de agosto. Reúne a decenas de miles de romeros de los valles del Pas y de Toranzo que acuden a pie subiendo por las colinas hasta la pradera del santuario barroco, destacando las procesiones tradicionales y el repique manual de campanas.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24015','religioso','Iglesia Parroquial de Santiago Apóstol y Ermita del Santo Cristo de la Veracruz','Solemnes cultos y viacrucis tradicionales en torno al 3 de mayo (Día de la Cruz). Los jornaleros y agricultores de La Loma acuden a pie desde las dehesas colindantes portando promesas de salud y exvotos, rememorando el rito secular de las rogativas agrarias por las lluvias.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18915','religioso','Iglesia Parroquial de la Purísima Concepción y Ermita del Santo Cristo de la Almoradilla','Fiestas grandes en honor al Cristo en el mes de octubre, destacando la multitudinaria bajada nocturna iluminada con antorchas. Fieles y jornaleros realizan marchas a pie desde los cortijos de los Montes Orientales para presentar fotografías y prendas de enfermos en su altar.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23056','religioso','Iglesia Parroquial de la Inmaculada Concepción y Ermita de Jesús Nazareno','Solemnes desfiles procesionales y viacrucis durante la Semana Santa (Interés Turístico Provincial), marcados por el canto de saetas autóctonas de interior. Goteo constante de labriegos de la Campiña de Jaén que acuden a depositar espigas de grano y exvotos metálicos artesanales en cumplimiento de promesas familiares de salud y salvación de cosechas.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18038','religioso','Iglesia Parroquial de la Santa Virgen de los Remedios y Ermita del Santo Cristo','Fiestas patronales y bajada tradicional en la primera quincena de agosto. Fieles y jornaleros del olivar y el cereal realizan marchas a pie nocturnas por las veredas de secano del norte granadino, cumpliendo el rito inmaterial de besar el pie de la imagen mariana y presentar fotografías de enfermos crónicos.','inventario_turismo_religioso_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39082','religioso','Santuario de Nuestra Señora de Valvanuz de Selaya e Iglesia de San Juan Bautista','Gran romería tradicional el 15 de agosto. Reúne a decenas de miles de romeros pasiegos que acuden portando bastones tradicionales, destacando el tradicional salto pasiego y las ofrendas de quesadas a la Virgen bajo la sombra del encinar sagrado, con el sonido de los romances sacros de los picayos.','inventario_turismo_religioso_pdf');
